def make_day_cell(status, top_value="", line_2="", line_3="", line_4="", line_5="", line_6="", numeric_hours=0, late_minutes_numeric=0):
    safe_values = [
        str(status or "").replace("|", "-"),
        str(top_value or "").replace("|", "-"),
        str(line_2 or "").replace("|", "-"),
        str(line_3 or "").replace("|", "-"),
        str(line_4 or "").replace("|", "-"),
        str(line_5 or "").replace("|", "-"),
        str(line_6 or "").replace("|", "-"),
        str(round2(numeric_hours or 0)),
        str(round2(late_minutes_numeric or 0))
    ]
    return "|".join(safe_values)

def combine_date_and_time(dt_str, time_value):
    if not time_value:
        return None

    date_obj = frappe.utils.getdate(dt_str)

    time_txt = str(time_value or "")
    if " " in time_txt:
        time_txt = time_txt.split(" ")[-1]

    return frappe.utils.get_datetime(str(date_obj) + " " + time_txt)

def add_hours_to_datetime(start_dt, hours_value):
    if not start_dt:
        return None

    hrs = float(hours_value or 0)
    if hrs <= 0:
        return None

    return frappe.utils.add_to_date(
        start_dt,
        hours=hrs,
        as_datetime=True
    )

def diff_minutes(start_dt, end_dt):
    if not start_dt or not end_dt:
        return 0.0

    start_dt = start_dt.replace(second=0, microsecond=0)
    end_dt = end_dt.replace(second=0, microsecond=0)

    seconds = (end_dt - start_dt).total_seconds()
    if seconds <= 0:
        return 0.0

    return float(int(seconds // 60))

def diff_hours(start_dt, end_dt):
    if not start_dt or not end_dt:
        return 0.0

    total_minutes = diff_minutes(start_dt, end_dt)
    return round2(total_minutes / 60.0)

def format_hhmm(dt_obj):
    if not dt_obj:
        return ""
    return frappe.utils.format_time(dt_obj, "HH:mm")

def get_shift_start_end_datetimes(shift_doc, dt):
    if not shift_doc:
        return [None, None]

    shift_start_dt = combine_date_and_time(dt, shift_doc.start_time)
    shift_end_dt = combine_date_and_time(dt, shift_doc.end_time)

    if shift_start_dt and shift_end_dt and shift_end_dt < shift_start_dt:
        shift_end_dt = frappe.utils.add_to_date(shift_end_dt, days=1, as_datetime=True)

    return [shift_start_dt, shift_end_dt]

def get_late_grace_minutes(shift_doc):
    if not shift_doc:
        return DEFAULT_LATE_ENTRY_GRACE_MINUTES
    return round2(shift_doc.late_entry_grace_period or 0)

def get_early_exit_grace_minutes(shift_doc):
    if not shift_doc:
        return 0.0
    return round2(shift_doc.early_exit_grace_period or 0)

def add_minutes(dt_obj, minutes_value):
    if not dt_obj:
        return None
    return frappe.utils.add_to_date(dt_obj, minutes=float(minutes_value or 0), as_datetime=True)

def make_interval(start_dt, end_dt, label):
    if not start_dt or not end_dt:
        return None
    if end_dt <= start_dt:
        return None
    return {
        "start": start_dt,
        "end": end_dt,
        "label": label or ""
    }

def merge_intervals(intervals):
    clean = []
    for it in intervals:
        if it and it.get("start") and it.get("end") and it.get("end") > it.get("start"):
            clean.append(it)

    sorted_intervals = sorted(clean, key=lambda x: x.get("start"))

    merged = []
    for it in sorted_intervals:
        if not merged:
            merged.append({
                "start": it.get("start"),
                "end": it.get("end"),
                "labels": [it.get("label") or ""]
            })
        else:
            last = merged[-1]
            if it.get("start") <= last.get("end"):
                if it.get("end") > last.get("end"):
                    last["end"] = it.get("end")
                lbls = last.get("labels") or []
                lbls.append(it.get("label") or "")
                last["labels"] = lbls
            else:
                merged.append({
                    "start": it.get("start"),
                    "end": it.get("end"),
                    "labels": [it.get("label") or ""]
                })

    return merged

def interval_minutes_total(intervals):
    merged = merge_intervals(intervals)
    total_minutes = 0.0
    for it in merged:
        total_minutes = total_minutes + diff_minutes(it.get("start"), it.get("end"))
    return total_minutes

def overlap_minutes(start_a, end_a, start_b, end_b):
    if not start_a or not end_a or not start_b or not end_b:
        return 0.0

    overlap_start = start_a
    if start_b > overlap_start:
        overlap_start = start_b

    overlap_end = end_a
    if end_b < overlap_end:
        overlap_end = end_b

    if overlap_end <= overlap_start:
        return 0.0

    return diff_minutes(overlap_start, overlap_end)

def intervals_overlap_minutes(intervals, start_dt, end_dt):
    total = 0.0
    for it in merge_intervals(intervals):
        total = total + overlap_minutes(it.get("start"), it.get("end"), start_dt, end_dt)
    return total

def intervals_outside_shift_minutes(intervals, shift_start_dt, shift_end_dt):
    total = 0.0

    for it in merge_intervals(intervals):
        interval_total = diff_minutes(it.get("start"), it.get("end"))
        inside_total = overlap_minutes(it.get("start"), it.get("end"), shift_start_dt, shift_end_dt)
        outside_total = interval_total - inside_total
        if outside_total > 0:
            total = total + outside_total

    return total

def resolve_exception_employee_doctype():
    parent_meta = frappe.get_meta("Attendance Exception")

    for df in parent_meta.fields:
        if df.fieldtype != "Table":
            continue

        child_dt = df.options
        if not child_dt:
            continue

        try:
            child_meta = frappe.get_meta(child_dt)
        except Exception:
            continue

        has_employee_field = False
        for cdf in child_meta.fields:
            if cdf.fieldname == "employee":
                has_employee_field = True
                break

        if has_employee_field:
            return child_dt

    return None

