def matches_summary_card(summary_card, row):
    if not summary_card:
        return True

    request_status = row.get("request_status")
    license_type = row.get("license_type")
    language = row.get("language")
    main_hq = row.get("main_hq")

    if summary_card == "total_requests":
        return True

    if summary_card == "draft_requests":
        return request_status == "Draft"

    if summary_card == "submitted_requests":
        return request_status == "Request Submitted"

    if summary_card == "under_verification_requests":
        return request_status == "Under Verification"

    if summary_card == "approved_requests":
        return request_status == "Approved"

    if summary_card == "rejected_requests":
        return request_status == "Rejected"

