        return license_type == summary_value

    if summary_card == "top_language":
        summary_value = norm(frappe.form_dict.get("summary_value"))
        if not summary_value:
            return True
        return language == summary_value

    if summary_card == "top_main_hq":
        summary_value = norm(frappe.form_dict.get("summary_value"))
        if not summary_value:
            return True
        return main_hq == summary_value

    if summary_card == "top_reviewer":
        summary_value = norm(frappe.form_dict.get("summary_value"))
        if not summary_value:
            return True
        return row.get("reviewed_by") == summary_value

