def build_manager_employee_scope(manager_employee, manager_user):
    scoped = []
    scoped_map = {}

    def add_scope(emp_code):
        if not emp_code:
            return

        emp_code = str(emp_code)
        if emp_code not in scoped_map:
            scoped.append(emp_code)
            scoped_map[emp_code] = 1

    if not manager_employee and not manager_user:
        return scoped

    if manager_employee:
        add_scope(manager_employee)

    all_active_employees = frappe.get_all(
        "Employee",
        filters={
            "status": "Active"
        },
        fields=[
            "name",
            "reports_to",
            "leave_approver",
            "department"
        ]
    )

    children_by_manager = {}

    for emp_row in all_active_employees:
        report_to_value = emp_row.get("reports_to")
        if report_to_value:
            report_to_value = str(report_to_value)
            if report_to_value not in children_by_manager:
                children_by_manager[report_to_value] = []
            children_by_manager[report_to_value].append(emp_row.get("name"))

        if manager_user and emp_row.get("leave_approver") == manager_user:
            add_scope(emp_row.get("name"))

    if manager_employee:
        managed_departments = frappe.get_all(
            "Department",
            filters={
                "department_head": manager_employee
            },
            fields=["name"]
        )

        managed_department_map = {}
        for dep_row in managed_departments:
            dep_name = dep_row.get("name")
            if dep_name:
                managed_department_map[str(dep_name)] = 1

        if managed_department_map:
            for emp_row in all_active_employees:
                emp_department = emp_row.get("department")
                if emp_department and str(emp_department) in managed_department_map:
                    add_scope(emp_row.get("name"))

        queue = [manager_employee]
        visited_manager_map = {}

        while queue:
            current_manager = queue.pop(0)
            if current_manager in visited_manager_map:
                continue

            visited_manager_map[current_manager] = 1
            child_list = children_by_manager.get(current_manager) or []

            for child_emp in child_list:
                add_scope(child_emp)
                queue.append(child_emp)

    return scoped

