        str(round2(numeric_hours or 0)),
        str(round2(late_minutes_numeric or 0))
    ]
    return "|".join(safe_values)

def combine_date_and_time(dt_str, time_value):
    if not time_value:
        return None

    date_obj = frappe.utils.getdate(dt_str)

    time_txt = str(time_value or "")
    if " " in time_txt:
        time_txt = time_txt.split(" ")[-1]

    return frappe.utils.get_datetime(str(date_obj) + " " + time_txt)

def add_hours_to_datetime(start_dt, hours_value):
    if not start_dt:
        return None

    hrs = float(hours_value or 0)
    if hrs <= 0:
        return None

    return frappe.utils.add_to_date(
        start_dt,
        hours=hrs,
        as_datetime=True
    )

def diff_minutes(start_dt, end_dt):
    if not start_dt or not end_dt:
        return 0.0

    start_dt = start_dt.replace(second=0, microsecond=0)
    end_dt = end_dt.replace(second=0, microsecond=0)

    seconds = (end_dt - start_dt).total_seconds()
    if seconds <= 0:
        return 0.0

    return float(int(seconds // 60))

def diff_hours(start_dt, end_dt):
    if not start_dt or not end_dt:
        return 0.0

    total_minutes = diff_minutes(start_dt, end_dt)
    return round2(total_minutes / 60.0)

def format_hhmm(dt_obj):
    if not dt_obj:
        return ""
    return frappe.utils.format_time(dt_obj, "HH:mm")

def get_shift_start_end_datetimes(shift_doc, dt):
    if not shift_doc:
        return [None, None]

    shift_start_dt = combine_date_and_time(dt, shift_doc.start_time)
    shift_end_dt = combine_date_and_time(dt, shift_doc.end_time)

    if shift_start_dt and shift_end_dt and shift_end_dt < shift_start_dt:
        shift_end_dt = frappe.utils.add_to_date(shift_end_dt, days=1, as_datetime=True)

    return [shift_start_dt, shift_end_dt]

def get_late_grace_minutes(shift_doc):
    if not shift_doc:
        return DEFAULT_LATE_ENTRY_GRACE_MINUTES
    return round2(shift_doc.late_entry_grace_period or 0)

def get_early_exit_grace_minutes(shift_doc):
    if not shift_doc:
