    for ex in exception_rows:
        exception_parent_map[ex.name] = ex

    exception_names = [d.name for d in exception_rows]

    resolved_exception_employee_doctype = resolve_exception_employee_doctype()

    exception_employee_rows_all = []
    exception_employee_rows = []

    if exception_names and resolved_exception_employee_doctype:
        exception_employee_rows_all = frappe.get_all(
            resolved_exception_employee_doctype,
            filters={
                "parent": ["in", exception_names]
            },
            fields=["parent", "employee"]
        )

    employee_allowed_map = {}
    for emp_code in employee_list:
        employee_allowed_map[str(emp_code)] = 1

    for child in exception_employee_rows_all:
        if str(child.employee) in employee_allowed_map:
            exception_employee_rows.append(child)

    exception_map = {}
    exception_type_counter = {}
    exception_employee_counter = {}
    exception_debug_map = {}

    for child in exception_employee_rows:
        parent_doc = exception_parent_map.get(child.parent)
        if not parent_doc:
            continue

        key = str(child.employee) + "||" + str(parent_doc.attendance_date)

        exception_debug_map[key] = {
            "exception_name": parent_doc.name,
            "exception_type": parent_doc.exception_type or "",
            "attendance_date": str(parent_doc.attendance_date),
            "manual_check_in": str(parent_doc.manual_check_in or ""),
            "manual_check_out": str(parent_doc.manual_check_out or ""),
            "waive_late_minutes": round2(parent_doc.waive_late_minutes or 0),
            "waive_early_exit_minutes": round2(parent_doc.waive_early_exit_minutes or 0)
        }

        if key not in exception_map:
            exception_map[key] = {
                "manual_check_in": None,
                "manual_check_out": None,
                "waive_late_minutes": 0.0,
                "waive_early_exit_minutes": 0.0,
                "items": []
            }

        item = exception_map[key]

        if parent_doc.manual_check_in:
            item["manual_check_in"] = parent_doc.manual_check_in

        if parent_doc.manual_check_out:
            item["manual_check_out"] = parent_doc.manual_check_out

        item["waive_late_minutes"] = item["waive_late_minutes"] + float(parent_doc.waive_late_minutes or 0)
        item["waive_early_exit_minutes"] = item["waive_early_exit_minutes"] + float(parent_doc.waive_early_exit_minutes or 0)

        exception_employee_counter[child.employee] = int(exception_employee_counter.get(child.employee) or 0) + 1

        ex_type = (parent_doc.exception_type or "").strip()
        if ex_type:
            item_list = item.get("items") or []
            item_list.append({
                "type": ex_type,
                "reason": parent_doc.reason or "",
                "details": parent_doc.details or ""
            })
            item["items"] = item_list
            exception_type_counter[ex_type] = exception_type_counter.get(ex_type, 0) + 1

    # -------------------------------------------------------------------------
    # Leave Application query
    # -------------------------------------------------------------------------
    leave_rows = []
    if employee_list:
        leave_rows = frappe.get_all(
            "Leave Application",
            filters={
                "employee": ["in", employee_list],
                "status": "Approved",
                "from_date": ["<=", to_date],
                "to_date": [">=", from_date]
            },
            fields=[
                "name",
                "employee",
                "leave_type",
                "from_date",
                "to_date",
                "half_day",
                "custom_hours",
                "custom_leave_start_time"
            ],
            order_by="employee asc, from_date asc"
        )

    def get_leave_day_hours(leave_row, emp, dt):
        leave_from = frappe.utils.getdate(leave_row.from_date)
        leave_to = frappe.utils.getdate(leave_row.to_date)
        target_date = frappe.utils.getdate(dt)

        if target_date < leave_from or target_date > leave_to:
            return {
                "hours": 0.0,
                "leave_type": leave_row.leave_type or "",
                "label": "",
                "is_hourly": 0,
                "start_dt": None,
                "end_dt": None
            }

        expected_day_hours = get_expected_hours(emp, dt)

        if leave_row.half_day:
            hrs = round2(leave_row.custom_hours or 0)
            if hrs <= 0 and expected_day_hours > 0:
                hrs = round2(expected_day_hours / 2.0)

            start_dt = None
            end_dt = None
            if leave_row.custom_leave_start_time and hrs > 0:
                start_dt = combine_date_and_time(dt, leave_row.custom_leave_start_time)
                end_dt = add_hours_to_datetime(start_dt, hrs)

            label = (leave_row.leave_type or "Leave") + " (" + str(hrs) + "h)"
            if start_dt and end_dt:
                label = (leave_row.leave_type or "Leave") + " " + format_hours_short(hrs) + " " + format_hhmm(start_dt) + " -> " + format_hhmm(end_dt)

            return {
                "hours": hrs,
                "leave_type": leave_row.leave_type or "",
                "label": label,
                "is_hourly": 1,
                "start_dt": start_dt,
                "end_dt": end_dt
            }

        return {
            "hours": round2(expected_day_hours),
            "leave_type": leave_row.leave_type or "",
            "label": (leave_row.leave_type or "Leave") + " (" + str(round2(expected_day_hours)) + "h)",
            "is_hourly": 0,
            "start_dt": None,
            "end_dt": None
        }

    leave_day_map = {}

    for leave_row in leave_rows:
        leave_from = frappe.utils.getdate(leave_row.from_date)
        leave_to = frappe.utils.getdate(leave_row.to_date)

        current_dt = leave_from
        while current_dt <= leave_to:
            if current_dt < from_date_obj or current_dt > to_date_obj:
                current_dt = frappe.utils.add_days(current_dt, 1)
                continue

            dt_str = str(current_dt)
            info = get_leave_day_hours(leave_row, leave_row.employee, dt_str)
            hrs = round2(info.get("hours") or 0)

            if hrs > 0:
                key = str(leave_row.employee) + "||" + dt_str

                if key not in leave_day_map:
                    leave_day_map[key] = {
                        "hours": 0.0,
                        "items": []
                    }

                leave_day_item = leave_day_map[key]
                leave_day_item["hours"] = leave_day_item["hours"] + hrs

                leave_items = leave_day_item.get("items") or []
                leave_items.append({
                    "leave_type": info.get("leave_type") or "",
                    "hours": hrs,
                    "label": info.get("label") or "",
                    "is_hourly": info.get("is_hourly") or 0,
                    "start_dt": info.get("start_dt"),
                    "end_dt": info.get("end_dt")
                })
                leave_day_item["items"] = leave_items

            current_dt = frappe.utils.add_days(current_dt, 1)

    for key in leave_day_map:
        leave_day_item = leave_day_map[key]
        leave_day_item["hours"] = round2(leave_day_item["hours"])

    # -------------------------------------------------------------------------
    # Attendance query (WFH / DUTY as timed intervals when hourly)
    # -------------------------------------------------------------------------
    # We no longer depend on Attendance.status for WFH / On Duty because ERPNext
    # may convert Attendance Request into Attendance with status = Present.
    # Attendance Activity is the source of truth for partial/multiple WFH/On Duty
    # activities in the same day.
    activity_rows = []
    if employee_list:
        activity_rows = frappe.get_all(
            "Attendance Activity",
            filters={
                "employee": ["in", employee_list],
                "attendance_date": ["between", [from_date, to_date]],
                "status": "Approved"
            },
            fields=[
                "name",
                "employee",
                "attendance_date",
                "activity_type",
                "from_time",
                "hours",
                "is_hourly",
                "source_doctype",
                "source_name"
            ],
            order_by="employee asc, attendance_date asc, from_time asc"
        )
        #frappe.msgprint("Activity Rows: " + str(len(activity_rows)))
    def normalize_activity_type_for_report(value):
        txt = str(value or "").strip()

        mapping = {
            "Work From Home": {
                "status_code": "WFH",
                "label": "Work From Home"
            },
            "WFH": {
                "status_code": "WFH",
                "label": "Work From Home"
            },
            "On Duty": {
                "status_code": "DUTY",
                "label": "On Duty"
            },
            "Duty": {
                "status_code": "DUTY",
                "label": "On Duty"
            },
            "Training": {
                "status_code": "DUTY",
                "label": "Training"
            },
            "Manual Work": {
                "status_code": "DUTY",
                "label": "Manual Work"
            }
        }

        return mapping.get(txt)

    non_onsite_map = {}

    for row in activity_rows:
        activity_info = normalize_activity_type_for_report(row.activity_type)
        if not activity_info:
            continue

        day_key = str(row.attendance_date)
        key = str(row.employee) + "||" + day_key

        hours = round2(row.hours or 0)
        if hours <= 0:
            continue

        is_hourly = 1 if row.is_hourly else 0
        start_dt = None
        end_dt = None

        if is_hourly:
            if not row.from_time:
                # Hourly activity without start time cannot be converted into an interval.
                # It will still be counted as fallback hours below.
                is_hourly = 0
            else:
                start_dt = combine_date_and_time(day_key, row.from_time)
                end_dt = add_hours_to_datetime(start_dt, hours)

                if not start_dt or not end_dt:
                    is_hourly = 0

        if key not in non_onsite_map:
            non_onsite_map[key] = {
                "items": [],
                "total_hours": 0.0
            }

        item = {
            "status": row.activity_type or "",
            "status_code": activity_info.get("status_code") or "",
            "label": activity_info.get("label") or "",
            "hours": round2(hours),
            "is_hourly": is_hourly,
            "start_dt": start_dt,
            "end_dt": end_dt,
            "activity_name": row.name,
            "source_doctype": row.source_doctype or "",
            "source_name": row.source_name or ""
        }

        item_list = non_onsite_map[key].get("items") or []
        item_list.append(item)
        non_onsite_map[key]["items"] = item_list
        non_onsite_map[key]["total_hours"] = round2(
            float(non_onsite_map[key].get("total_hours") or 0) + hours
        )
    # -------------------------------------------------------------------------
    # Build employee/day matrix
    # -------------------------------------------------------------------------
    employees_map = {}

    for emp in employee_list:
        emp_details = employee_details_map.get(emp, {})

        base_row = {
            "employee": emp or "",
            "employee_number": emp_details.get("employee_number") or emp or "",
            "employee_name": emp_details.get("employee_name") or "",
            "company": emp_details.get("company") or "",
            "branch": emp_details.get("branch") or "",
            "department": emp_details.get("department") or "",
            "designation": emp_details.get("designation") or "",
            "grade": emp_details.get("grade") or "",
            "gender": emp_details.get("gender") or "",
            "default_shift": emp_details.get("default_shift") or ""
        }

        for dt in date_list:
            safe_dt = date_field_map[dt]

            if not day_matches_shift_filter(emp, dt):
                base_row[safe_dt] = ""
                base_row[safe_dt + "_leave_hours"] = 0.0
                base_row[safe_dt + "_overtime_hours"] = 0.0
                base_row[safe_dt + "_early_exit_minutes"] = 0.0
                base_row[safe_dt + "_waived_minutes"] = 0.0
                continue

            day_off_info = get_day_off_info(emp, dt)
            expected_day_hours = get_expected_hours(emp, dt)

            key = str(emp) + "||" + str(dt)

            day_checkin = checkin_day_map.get(key, {})
            day_exception = exception_map.get(key, {})
            day_leave = leave_day_map.get(key, {"hours": 0.0, "items": []})
            day_non_onsite = non_onsite_map.get(key)

            if selected_exception_type_drilldown:
                matched_exception = 0
                for exi in day_exception.get("items", []):
                    ex_type_value = str(exi.get("type") or "").strip()
                    selected_value = str(selected_exception_type_drilldown).strip()
                    if ex_type_value == selected_value:
                        matched_exception = 1
                        break

                if not matched_exception:
                    base_row[safe_dt] = ""
                    base_row[safe_dt + "_leave_hours"] = 0.0
                    base_row[safe_dt + "_overtime_hours"] = 0.0
                    base_row[safe_dt + "_early_exit_minutes"] = 0.0
                    continue

            first_in_dt = day_checkin.get("first_in")
            last_out_dt = day_checkin.get("last_out")

            manual_in_dt = combine_date_and_time(dt, day_exception.get("manual_check_in"))
            manual_out_dt = combine_date_and_time(dt, day_exception.get("manual_check_out"))

            used_manual_in = False
            used_manual_out = False

            if (not first_in_dt) and manual_in_dt:
                first_in_dt = manual_in_dt
                used_manual_in = True

            if (not last_out_dt) and manual_out_dt:
                last_out_dt = manual_out_dt
                used_manual_out = True

            leave_hours = round2(day_leave.get("hours") or 0)

            if day_off_info.get("is_holiday") and (not first_in_dt) and (not last_out_dt) and (not day_non_onsite) and leave_hours <= 0:
                if day_off_info.get("status") == "WEEKEND":
                    base_row[safe_dt] = make_day_cell("WEEKEND", "Weekend", "", "", "", "", "", 0, 0)
                else:
                    holiday_name = day_off_info.get("label") or "Holiday"
                    base_row[safe_dt] = make_day_cell("HOLIDAY", "Holiday", holiday_name, "", "", "", "", 0, 0)

                base_row[safe_dt + "_leave_hours"] = 0.0
                base_row[safe_dt + "_overtime_hours"] = 0.0
                base_row[safe_dt + "_early_exit_minutes"] = 0.0
                continue

            # -----------------------------------------------------------------
            # Build work intervals: Checkin + hourly WFH/DUTY
            # -----------------------------------------------------------------
            work_intervals = []
            activity_lines = []
            fallback_non_onsite_hours = 0.0
            main_non_onsite_status = ""
            main_non_onsite_label = ""

            if first_in_dt and last_out_dt:
                work_intervals.append(make_interval(first_in_dt, last_out_dt, "Checkin"))

            if day_non_onsite:
                for ni in day_non_onsite.get("items") or []:
                    status_code = ni.get("status_code") or ""
                    label = ni.get("label") or ""
                    hours = round2(ni.get("hours") or 0)

                    if not main_non_onsite_status:
                        main_non_onsite_status = status_code
                        main_non_onsite_label = label

                    if ni.get("is_hourly") and ni.get("start_dt") and ni.get("end_dt"):
                        work_intervals.append(make_interval(ni.get("start_dt"), ni.get("end_dt"), status_code))
                        activity_lines.append(label + " " + format_hours_short(hours) + " " + format_hhmm(ni.get("start_dt")) + " -> " + format_hhmm(ni.get("end_dt")))
                    else:
                        fallback_non_onsite_hours = fallback_non_onsite_hours + hours
                        activity_lines.append(label + " " + format_hours_short(hours))

            # Onsite or mixed
            if first_in_dt or last_out_dt:
                in_txt = format_hhmm(first_in_dt) if first_in_dt else "?"
                out_txt = format_hhmm(last_out_dt) if last_out_dt else "?"

                if first_in_dt:
                    in_txt = in_txt + " (" + ("M" if used_manual_in else "A") + ")"
                if last_out_dt:
                    out_txt = out_txt + " (" + ("M" if used_manual_out else "A") + ")"

                line_2 = in_txt + " -> " + out_txt

                day_custom_over_night_minutes = float(day_checkin.get("last_out_custom_over_night") or 0)
                day_custom_over_night_hours = round2(day_custom_over_night_minutes / 60.0)

                merged_minutes = interval_minutes_total(work_intervals)
                actual_work_hours = round2(merged_minutes / 60.0)

                if day_custom_over_night_hours > 0:
                    actual_work_hours = actual_work_hours + day_custom_over_night_hours

                if fallback_non_onsite_hours > 0:
                    actual_work_hours = actual_work_hours + fallback_non_onsite_hours

                leave_intervals = []

                if day_leave.get("items"):
                    for li in day_leave.get("items"):
                        if li.get("start_dt") and li.get("end_dt"):
                            leave_intervals.append(
                                make_interval(
                                    li.get("start_dt"),
                                    li.get("end_dt"),
                                    "Leave"
                                )
                            )

                justified_intervals = []

                for wi in work_intervals:
                    justified_intervals.append(wi)

                for li in leave_intervals:
                    justified_intervals.append(li)

                shift_name = get_effective_shift(emp, dt, employee_date_shift_map, employee_default_shift)
                shift_doc = shift_map.get(shift_name) if shift_name else None

                raw_late_minutes = 0.0
                effective_late_minutes = 0.0
                raw_early_exit_minutes = 0.0
                effective_early_exit_minutes = 0.0
                applied_waived_minutes = 0.0
                overtime_hours = 0.0

                shift_start_dt = None
                shift_end_dt = None
                grace_in = 0.0
                grace_out = 0.0

                if shift_doc and not day_off_info.get("is_holiday"):
                    shift_range = get_shift_start_end_datetimes(shift_doc, dt)
                    shift_start_dt = shift_range[0]
                    shift_end_dt = shift_range[1]

                    grace_in = get_late_grace_minutes(shift_doc)
                    grace_out = get_early_exit_grace_minutes(shift_doc)

                    if first_in_dt and shift_start_dt:
                        grace_in_dt = add_minutes(shift_start_dt, grace_in)
                        raw_late_minutes = diff_minutes(grace_in_dt, first_in_dt)

                        if raw_late_minutes < 0:
                            raw_late_minutes = 0.0

                        covered_late_minutes = intervals_overlap_minutes(justified_intervals, grace_in_dt, first_in_dt)
                        raw_late_minutes = raw_late_minutes - covered_late_minutes
                        if raw_late_minutes < 0:
                            raw_late_minutes = 0.0

                    waived_late = round2(day_exception.get("waive_late_minutes") or 0)
                    effective_late_minutes = raw_late_minutes - waived_late
                    if effective_late_minutes < 0:
                        effective_late_minutes = 0.0

                    applied_waived_late_minutes = raw_late_minutes - effective_late_minutes
                    if applied_waived_late_minutes > 0:
                        applied_waived_minutes = applied_waived_minutes + applied_waived_late_minutes

                    if last_out_dt and shift_end_dt:
                        early_cutoff_dt = add_minutes(shift_end_dt, 0 - grace_out)
                        raw_early_exit_minutes = diff_minutes(last_out_dt, early_cutoff_dt)

                        if raw_early_exit_minutes < 0:
                            raw_early_exit_minutes = 0.0

                        covered_early_minutes = intervals_overlap_minutes(justified_intervals, last_out_dt, early_cutoff_dt)
                        raw_early_exit_minutes = raw_early_exit_minutes - covered_early_minutes
                        if raw_early_exit_minutes < 0:
                            raw_early_exit_minutes = 0.0

                        waived_early = round2(day_exception.get("waive_early_exit_minutes") or 0)
                        effective_early_exit_minutes = raw_early_exit_minutes - waived_early
                        if effective_early_exit_minutes < 0:
                            effective_early_exit_minutes = 0.0

                        applied_waived_early_minutes = raw_early_exit_minutes - effective_early_exit_minutes
                        if applied_waived_early_minutes > 0:
                            applied_waived_minutes = applied_waived_minutes + applied_waived_early_minutes

                    if shift_start_dt and shift_end_dt:
                        overtime_minutes = intervals_outside_shift_minutes(work_intervals, shift_start_dt, shift_end_dt)
                        overtime_hours = round2(overtime_minutes / 60.0)

                top_value = format_hours_short(actual_work_hours)
                line_3 = ""
                line_4 = ""
                line_5 = ""
                line_6 = ""

                waived_late_display = round2(day_exception.get("waive_late_minutes") or 0)
                if raw_late_minutes > 0:
                    if waived_late_display > 0:
                        if effective_late_minutes > 0:
                            line_3 = "Late " + format_minutes_short(effective_late_minutes) + " (Waived " + format_minutes_short(waived_late_display) + ")"
                        else:
                            line_3 = "Late " + format_minutes_short(raw_late_minutes) + " (Waived " + format_minutes_short(waived_late_display) + ")"
                    else:
                        line_3 = "Late " + format_minutes_short(raw_late_minutes)

                waived_early_display = round2(day_exception.get("waive_early_exit_minutes") or 0)
                if raw_early_exit_minutes > 0:
                    if waived_early_display > 0:
                        if effective_early_exit_minutes > 0:
                            line_4 = "Early Exit " + format_minutes_short(effective_early_exit_minutes) + " (Waived " + format_minutes_short(waived_early_display) + ")"
                        else:
                            line_4 = "Early Exit " + format_minutes_short(raw_early_exit_minutes) + " (Waived " + format_minutes_short(waived_early_display) + ")"
                    else:
                        line_4 = "Early Exit " + format_minutes_short(raw_early_exit_minutes)

                if overtime_hours > 0:
                    line_5 = "Overtime " + format_hours_short(overtime_hours)

                extra_lines = []

                for al in activity_lines:
                    if al:
                        extra_lines.append(al)

                if leave_hours > 0 and day_leave.get("items"):
                    leave_txt_parts = []
                    for li in day_leave.get("items"):
                        if li.get("is_hourly") and li.get("start_dt") and li.get("end_dt"):
                            leave_txt_parts.append(
                                format_hours_short(li.get("hours") or 0) + " " + format_hhmm(li.get("start_dt")) + " -> " + format_hhmm(li.get("end_dt")) + " (" + (li.get("leave_type") or "Leave") + ")"
                            )
                        else:
                            leave_txt_parts.append(
                                format_hours_short(li.get("hours") or 0) + " (" + (li.get("leave_type") or "Leave") + ")"
                            )
                    extra_lines.append("Leave " + ", ".join(leave_txt_parts))

                if debug_mode:
                    debug_parts = []
                    debug_parts.append("Debug Key " + str(key))

                    debug_exception = exception_debug_map.get(key)
                    if debug_exception:
                        debug_parts.append("Exception Found")
                        debug_parts.append("Name " + str(debug_exception.get("exception_name") or ""))
                        debug_parts.append("Type " + str(debug_exception.get("exception_type") or ""))
                        debug_parts.append("Waive Early " + str(debug_exception.get("waive_early_exit_minutes") or 0))
                        debug_parts.append("Waive Late " + str(debug_exception.get("waive_late_minutes") or 0))
                    else:
                        debug_parts.append("Exception NOT Found")

                    debug_parts.append("Raw Early " + format_minutes_short(raw_early_exit_minutes))
                    debug_parts.append("Effective Early " + format_minutes_short(effective_early_exit_minutes))
                    debug_parts.append("Raw Late " + format_minutes_short(raw_late_minutes))
                    debug_parts.append("Effective Late " + format_minutes_short(effective_late_minutes))

                    extra_lines.append("Debug " + " - ".join(debug_parts))

                if extra_lines:
                    line_6 = " | ".join(extra_lines)

                status_code = "PRESENT"
                if (not first_in_dt) or (not last_out_dt):
                    status_code = "INCOMPLETE"

                base_row[safe_dt] = make_day_cell(
                    status_code,
                    top_value,
                    line_2,
                    line_3,
                    line_4,
                    line_5,
                    line_6,
                    actual_work_hours,
                    effective_late_minutes
                )

                base_row[safe_dt + "_leave_hours"] = round2(leave_hours)
                base_row[safe_dt + "_overtime_hours"] = round2(overtime_hours)
                base_row[safe_dt + "_early_exit_minutes"] = round2(effective_early_exit_minutes)
                base_row[safe_dt + "_waived_minutes"] = round2(applied_waived_minutes)
                continue

            # Non-on-site only: WFH / DUTY without checkin
            if day_non_onsite:
                non_onsite_minutes = interval_minutes_total(work_intervals)
                non_onsite_hours = round2(non_onsite_minutes / 60.0)

                if non_onsite_hours <= 0:
                    non_onsite_hours = round2(day_non_onsite.get("total_hours") or 0)

