            ]
        )

        for shift_row in shift_rows:
            shift_map[shift_row.name] = shift_row

            if shift_row.holiday_list and shift_row.holiday_list not in holiday_list_seen:
                holiday_list_names.append(shift_row.holiday_list)
                holiday_list_seen[shift_row.holiday_list] = 1

    if shift_type_filter and employee_list:
        filtered_employee_rows = []
        filtered_employee_list = []

        for er in employee_rows:
            emp_code = er.name
            matched_shift = False

            for dt in date_list:
                effective_shift = get_effective_shift(emp_code, dt, employee_date_shift_map, employee_default_shift)
                if effective_shift == shift_type_filter:
