            "status": "",
            "top_value": "",
            "punches": "",
            "late": "",
            "early": "",
            "overtime_text": "",
            "extra": "",
            "numeric_hours": 0.0,
            "late_minutes": 0.0
        }

        if len(parts) > 0:
            out["status"] = parts[0] or ""
        if len(parts) > 1:
            out["top_value"] = parts[1] or ""
        if len(parts) > 2:
            out["punches"] = parts[2] or ""
        if len(parts) > 3:
            out["late"] = parts[3] or ""
        if len(parts) > 4:
            out["early"] = parts[4] or ""
        if len(parts) > 5:
            out["overtime_text"] = parts[5] or ""
        if len(parts) > 6:
            out["extra"] = parts[6] or ""
        if len(parts) > 7:
            out["numeric_hours"] = round2(parts[7] or 0)
        if len(parts) > 8:
            out["late_minutes"] = round2(parts[8] or 0)

        return out

