def norm(v):
    if v is None:
        return None
    v = str(v).strip()
    if (not v) or (v.lower() in ("null", "none", "undefined", "nan")):
        return None
    return v

def norm_key(v, default_value="Unspecified"):
    v = norm(v)
    if v:
        return v
    return default_value

def safe_date(v):
    v = norm(v)
    if not v:
        return None
    try:
        return frappe.utils.getdate(v)
    except Exception:
        return None

def parse_json(value):
    if not value:
        return {}

    try:
        data = json.loads(value)
        if data:
            return data
    except Exception:
        return {}

    return {}

def num(v):
    try:
        return float(v or 0)
    except Exception:
        return 0.0

def get_metric(summary, key):
    if not summary:
        return 0.0

    metrics = {}
    try:
        metrics = summary.get("metrics") or {}
    except Exception:
        metrics = {}

    try:
        value = metrics.get(key)
        if value is not None:
            return num(value)
    except Exception:
        pass

    try:
        value = summary.get(key)
        if value is not None:
            return num(value)
    except Exception:
        pass

    return 0.0

def inc(d, key, step):
    d[key] = d.get(key, 0) + step

def add_perf(d, key, views, comments, shares, likes, engagement, materials_count, posts_count):
    if not d.get(key):
        d[key] = {
            "views": 0,
            "comments": 0,
            "shares": 0,
            "likes": 0,
            "engagement_total": 0,
            "materials_count": 0,
            "posts_count": 0
        }

    row = d.get(key)
    row["views"] = row.get("views", 0) + views
    row["comments"] = row.get("comments", 0) + comments
    row["shares"] = row.get("shares", 0) + shares
    row["likes"] = row.get("likes", 0) + likes
    row["engagement_total"] = row.get("engagement_total", 0) + engagement
    row["materials_count"] = row.get("materials_count", 0) + materials_count
    row["posts_count"] = row.get("posts_count", 0) + posts_count

def dict_to_chart(d):
    out = []
    for k in d:
        out.append({
            "label": k,
            "value": d.get(k, 0)
        })
    out.sort(key=lambda x: x.get("value", 0), reverse=True)
    return out

def top_n(items, n, value_key):
    items.sort(key=lambda x: x.get(value_key, 0), reverse=True)
    return items[:n]

def perf_to_table(d, label_key):
    out = []
    for k in d:
        row = d.get(k) or {}
        views = row.get("views", 0)
        engagement = row.get("engagement_total", 0)

        rate = 0
        if views:
            rate = round((float(engagement) / float(views)) * 100, 2)

        out.append({
            label_key: k,
            "materials_count": row.get("materials_count", 0),
            "posts_count": row.get("posts_count", 0),
            "views": views,
            "comments": row.get("comments", 0),
            "shares": row.get("shares", 0),
            "likes": row.get("likes", 0),
            "engagement_total": engagement,
            "engagement_rate": rate
        })

    out.sort(key=lambda x: x.get("engagement_total", 0), reverse=True)
    return out

