def norm(v):
    if v is None:
        return ""
    return str(v).strip()


def meta_has_field(doctype_name, fieldname):
    exists = 0
    try:
        meta = frappe.get_meta(doctype_name)
        for df in meta.fields:
            if df.fieldname == fieldname:
                exists = 1
    except Exception:
        exists = 0
    return exists


def get_meta_field(doctype_name, fieldname):
    try:
        meta = frappe.get_meta(doctype_name)
        for df in meta.fields:
            if df.fieldname == fieldname:
                return df
    except Exception:
        return None
    return None


def set_if_exists(doc, fieldname, value):
    if meta_has_field(doc.doctype, fieldname):
        doc.set(fieldname, value)


def first_select_option(options):
    selected = ""
    parts = norm(options).split("\n")
    for p in parts:
        if not selected and norm(p):
            selected = norm(p)
    return selected


def first_doc_name(doctype_name):
    result = ""
    if not frappe.db.exists("DocType", doctype_name):
        return result

    try:
        rows = frappe.get_all(doctype_name, fields=["name"], limit=1)
        if rows:
            result = rows[0].get("name")
    except Exception:
        result = ""

    return result


def guess_link_value(options):
    if options and frappe.db.exists("DocType", options):
        return first_doc_name(options)
    return ""


