def fill_required_fields(doc):
    try:
        meta = frappe.get_meta(doc.doctype)
        for df in meta.fields:
            if df.reqd and df.fieldname:
                if df.fieldtype not in ("Section Break", "Column Break", "Tab Break", "Fold", "HTML", "Table", "Table MultiSelect"):
                    current = doc.get(df.fieldname)
                    if current is None or current == "":
                        value = guess_required_value(df)
                        if value is not None:
                            doc.set(df.fieldname, value)
    except Exception as e:
        warnings.append("Could not fill required fields for " + doc.doctype + ": " + str(e))


def force_doc_name(doc, docname):
    if docname:
        try:
            doc.name = docname
        except Exception:
            pass


def save_or_insert(doc, label, was_existing):
    fill_required_fields(doc)

    if was_existing:
        doc.save(ignore_permissions=True)
        updated.append(label)
    else:
        doc.insert(ignore_permissions=True)
        created.append(label)

    return doc.name


def find_existing_by_fields(doctype_name, title_value, candidates):
    result = ""

    if frappe.db.exists(doctype_name, title_value):
        return title_value

    for f in candidates:
        if not result and meta_has_field(doctype_name, f):
            try:
                rows = frappe.get_all(
                    doctype_name,
                    filters={f: title_value},
                    fields=["name"],
                    limit=1
                )
                if rows:
                    result = rows[0].get("name")
            except Exception:
                result = result

    return result


def set_title_fields(doc, title_value, candidates):
    for f in candidates:
        set_if_exists(doc, f, title_value)


def ensure_named_doc(doctype_name, docname, title_value, candidates):
    if not frappe.db.exists("DocType", doctype_name):
        frappe.throw("Missing DocType: " + doctype_name)

    existing_name = ""

    if frappe.db.exists(doctype_name, docname):
        existing_name = docname

    if not existing_name:
        existing_name = find_existing_by_fields(doctype_name, title_value, candidates)

    was_existing = 0

    if existing_name:
        doc = frappe.get_doc(doctype_name, existing_name)
        was_existing = 1
    else:
        doc = frappe.get_doc({
            "doctype": doctype_name
        })
        force_doc_name(doc, docname)

    set_title_fields(doc, title_value, candidates)
    return save_or_insert(doc, doctype_name + ": " + title_value, was_existing)


def first_existing_entity(values):
    result = ""

    for v in values:
        if not result:
            if frappe.db.exists("Entity-all", v):
                result = v

    fields = ["entity", "entity_name", "entity_title", "title", "organization_name", "name1"]

    for v2 in values:
        if not result:
            for f in fields:
                if not result and meta_has_field("Entity-all", f):
                    try:
                        rows = frappe.get_all(
                            "Entity-all",
                            filters={f: v2},
                            fields=["name"],
                            limit=1
                        )
                        if rows:
                            result = rows[0].get("name")
                    except Exception:
                        result = result

    return result


def clear_table_if_exists(doc, table_field):
    if meta_has_field(doc.doctype, table_field):
        doc.set(table_field, [])


def append_child_adaptive(doc, table_field, values):
    if not meta_has_field(doc.doctype, table_field):
        return None

    df = get_meta_field(doc.doctype, table_field)
    if not df:
        return None

    child_dt = norm(df.options)
    if not child_dt:
        return None

    child = doc.append(table_field, {})

    for k in values:
        if meta_has_field(child_dt, k):
            child.set(k, values.get(k))

    fill_required_fields(child)
    return child


