    return result


def upsert_publication(pub_docname, item_title, platform, reach, views, likes, comments, shares, engagement, sentiment, score, url):
    item_id = item_id_by_title(production_name, item_title)

    if not item_id:
        warnings.append("Missing item for publication: " + item_title + " / " + platform)
        return ""

    if frappe.db.exists("Media Publication", pub_docname):
        pub = frappe.get_doc("Media Publication", pub_docname)
        was_existing = 1
    else:
        existing = ""
        try:
            rows = frappe.get_all(
                "Media Publication",
                filters={
                    "media_production_test": production_name,
                    "production_item_id": item_id,
                    "platform": platform
                },
                fields=["name"],
                limit=1
            )
            if rows:
                existing = rows[0].get("name")
        except Exception:
            existing = ""

        if existing:
            pub = frappe.get_doc("Media Publication", existing)
            was_existing = 1
        else:
            pub = frappe.get_doc({
                "doctype": "Media Publication"
            })
            force_doc_name(pub, pub_docname)
            was_existing = 0

