def norm(v):
    if v is None:
        return None
    v = str(v).strip()
    if (not v) or (v.lower() in ("null", "none", "undefined", "nan")):
        return None
    return v


def norm_key(v, default_value="Unspecified"):
    v = norm(v)
    if v:
        return v
    return default_value


def safe_date(v):
    v = norm(v)
    if not v:
        return None

    try:
        return frappe.utils.getdate(v)
    except Exception:
        return None


def safe_datetime_date(v):
    v = norm(v)
    if not v:
        return None

    try:
        return frappe.utils.getdate(v)
    except Exception:
        return None


def num(v):
    try:
        return float(v or 0)
    except Exception:
        return 0.0


def int_num(v):
    try:
        return int(float(v or 0))
    except Exception:
        return 0


def round2(v):
    try:
        return round(float(v or 0), 2)
    except Exception:
        return 0


def parse_json(value):
    if not value:
        return {}

    try:
        data = json.loads(value)
        if data:
            return data
    except Exception:
        return {}

    return {}


def get_nested_metric(raw_json, key):
    if not raw_json:
        return 0

    metrics = {}
    try:
        metrics = raw_json.get("metrics") or {}
    except Exception:
        metrics = {}

    try:
        if metrics.get(key) is not None:
            return num(metrics.get(key))
    except Exception:
        pass

    try:
        if raw_json.get(key) is not None:
            return num(raw_json.get(key))
    except Exception:
        pass

    return 0


def inc(d, key, step):
    d[key] = d.get(key, 0) + step


def add_sum(d, key, field, step):
    if not d.get(key):
        d[key] = {}
    row = d.get(key)
    row[field] = row.get(field, 0) + step


def make_perf_row():
    return {
        "materials_count": 0,
        "publications_count": 0,
        "views": 0,
        "reach": 0,
        "impressions": 0,
        "likes": 0,
        "comments": 0,
