        "reactions_total": 0,
        "engagement_total": 0
    }


def add_perf(d, key, materials_count, publications_count, views, reach, impressions, likes, comments, shares, saves, reactions_total, engagement_total):
    if not d.get(key):
        d[key] = make_perf_row()

    row = d.get(key)
    row["materials_count"] = row.get("materials_count", 0) + materials_count
    row["publications_count"] = row.get("publications_count", 0) + publications_count
    row["views"] = row.get("views", 0) + views
    row["reach"] = row.get("reach", 0) + reach
    row["impressions"] = row.get("impressions", 0) + impressions
    row["likes"] = row.get("likes", 0) + likes
    row["comments"] = row.get("comments", 0) + comments
    row["shares"] = row.get("shares", 0) + shares
    row["saves"] = row.get("saves", 0) + saves
    row["reactions_total"] = row.get("reactions_total", 0) + reactions_total
    row["engagement_total"] = row.get("engagement_total", 0) + engagement_total


def dict_to_chart(d):
    out = []
    for k in d:
        out.append({
            "label": k,
            "value": d.get(k, 0)
        })

    out.sort(key=lambda x: x.get("value", 0), reverse=True)
    return out


def perf_to_table(d, label_key):
    out = []
    for k in d:
        row = d.get(k) or {}

        views = row.get("views", 0)
        reach = row.get("reach", 0)
        engagement = row.get("engagement_total", 0)

        engagement_rate = 0
        if views:
            engagement_rate = round2((float(engagement) / float(views)) * 100)

        reach_engagement_rate = 0
        if reach:
            reach_engagement_rate = round2((float(engagement) / float(reach)) * 100)

        item = {
            label_key: k,
            "materials_count": row.get("materials_count", 0),
            "publications_count": row.get("publications_count", 0),
            "views": views,
            "reach": reach,
            "impressions": row.get("impressions", 0),
