            "comments": row.get("comments", 0),
            "shares": row.get("shares", 0),
            "saves": row.get("saves", 0),
            "reactions_total": row.get("reactions_total", 0),
            "engagement_total": engagement,
            "engagement_rate": engagement_rate,
            "reach_engagement_rate": reach_engagement_rate
        }

        out.append(item)

    out.sort(key=lambda x: x.get("engagement_total", 0), reverse=True)
    return out


def top_n(items, n, value_key):
    items.sort(key=lambda x: x.get(value_key, 0), reverse=True)
    return items[:n]


def month_key(dt):
    if not dt:
        return "Unspecified"
    return str(dt.year) + "-" + str(dt.month).zfill(2)


def date_in_range(dt, from_dt, to_dt):
    if not dt:
        return False
    if from_dt and dt < from_dt:
        return False
    if to_dt and dt > to_dt:
        return False
    return True


def add_filter_value(d, key, value):
    value = norm(value)
    if not value:
        return
    if not d.get(key):
        d[key] = {}
    row = d.get(key)
    row[value] = 1


def filter_values_to_list(d, key):
    out = []
    row = d.get(key) or {}
    for k in row:
        out.append(k)
    out.sort()
    return out


def get_doc_label(doctype_name, name_value):
    name_value = norm(name_value)
    if not name_value:
        return ""

    if not frappe.db.exists("DocType", doctype_name):
        return name_value

    if not frappe.db.exists(doctype_name, name_value):
        return name_value

    try:
        meta = frappe.get_meta(doctype_name)
        title_field = norm(meta.get("title_field"))
        if title_field:
            val = frappe.db.get_value(doctype_name, name_value, title_field)
            if val:
                return str(val)
    except Exception:
        pass

    return name_value


def get_entity_type(entity_name):
    entity_name = norm(entity_name)
    if not entity_name:
        return ""

    if not frappe.db.exists("DocType", "Entity-all"):
        return ""

    if not frappe.db.exists("Entity-all", entity_name):
        return ""

    possible = [
        "entity_type",
        "type",
        "entity_category",
        "organization_type"
    ]

    for f in possible:
        try:
            val = frappe.db.get_value("Entity-all", entity_name, f)
            if val:
                return str(val)
        except Exception:
            pass

    return ""


def score_material(reach, views, engagement, sentiment_score):
    reach_score = 0
    views_score = 0
    engagement_score = 0
    sentiment_part = 0

    if reach:
        reach_score = min(float(reach) / 1000000.0, 1.0) * 30.0

    if views:
        views_score = min(float(views) / 1000000.0, 1.0) * 20.0

    if engagement:
        engagement_score = min(float(engagement) / 100000.0, 1.0) * 35.0

    try:
        sentiment_part = ((float(sentiment_score or 0) + 1.0) / 2.0) * 15.0
    except Exception:
        sentiment_part = 0

    return round2(reach_score + views_score + engagement_score + sentiment_part)


def get_first_child_value(parent_doc, table_field, child_field):
    rows = parent_doc.get(table_field) or []
    for r in rows:
        if r.get(child_field):
            return r.get(child_field)
    return ""


