# Dynamic filter options from source doctypes / fields
# ---------------------------------------------------------
# Important:
# These filter options are NOT built from the filtered dashboard result.
# They are read from the related DocTypes / Link targets / Select options.
# This means the filter dropdowns can show all available plans, platforms,
# campaigns, goals, messages, audiences, entities, sources, and statuses.

def get_link_or_select_options(source_dt, fieldname):
    out = []
    seen = {}

    if not frappe.db.exists("DocType", source_dt):
        return out

    try:
        meta = frappe.get_meta(source_dt)
    except Exception:
        return out

    target_dt = ""
    field_type = ""

    try:
        for df in meta.fields:
            if df.fieldname == fieldname:
                target_dt = df.options or ""
                field_type = df.fieldtype or ""
                break
    except Exception:
        target_dt = ""
        field_type = ""

    # If the field is Link, read all records from the linked DocType
    if field_type == "Link" and target_dt and frappe.db.exists("DocType", target_dt):
        try:
            rows = frappe.get_all(
                target_dt,
                fields=["name"],
                limit_page_length=0
            )

            for r in rows:
                v = norm(r.get("name"))
                if v and not seen.get(v):
                    out.append(v)
                    seen[v] = 1

        except Exception:
            out = []

    # If the field is Select, read all options from field definition
    elif field_type == "Select" and target_dt:
        try:
            parts = str(target_dt).split("\n")
            for p in parts:
                v2 = norm(p)
                if v2 and not seen.get(v2):
                    out.append(v2)
                    seen[v2] = 1
        except Exception:
            out = []

    # Fallback for Data / Small Text / fields that are not Link or Select:
    # read distinct non-empty values from existing records
    else:
        try:
            rows2 = frappe.get_all(
                source_dt,
                fields=[fieldname],
                limit_page_length=0
            )

            for r2 in rows2:
                v3 = norm(r2.get(fieldname))
                if v3 and not seen.get(v3):
                    out.append(v3)
                    seen[v3] = 1

        except Exception:
            out = []

    out.sort()
    return out


