# -----------------------------------------------------------------------------
# 3) Helpers
# -----------------------------------------------------------------------------
def norm(value):
    if value is None:
        return ""
    return str(value).strip()

def to_int(value):
    try:
        return int(float(value or 0))
    except Exception:
        return 0

def clean_label(value, fallback):
    txt = norm(value)
    if txt:
        return txt
    return fallback

def add_counter(counter, key, amount):
    safe_key = clean_label(key, "Unspecified")
    counter[safe_key] = int(counter.get(safe_key, 0)) + int(amount or 0)

def add_nested_counter(matrix, row_key, col_key, amount):
    safe_row = clean_label(row_key, "No Entity")
    safe_col = clean_label(col_key, "Unspecified")

    if safe_row not in matrix:
        matrix[safe_row] = {}

    row_obj = matrix.get(safe_row) or {}
    row_obj[safe_col] = int(row_obj.get(safe_col, 0)) + int(amount or 0)
    matrix[safe_row] = row_obj

def append_unique(target_list, seen_map, value):
    txt = norm(value)
    if not txt:
        return

    if txt not in seen_map:
        target_list.append(txt)
        seen_map[txt] = 1

def list_from_counter(counter):
    out = []
    keys = sorted(counter.keys())

    for key in keys:
        out.append({
            "label": key,
            "value": int(counter.get(key, 0))
        })

    return out

def has_field(doctype, fieldname):
    meta = frappe.get_meta(doctype)
    if meta.has_field(fieldname):
        return 1
    return 0

def get_public_opinion_match(value):
    txt = norm(value).lower()
    txt = txt.replace("_", " ")
    txt = txt.replace("-", " ")

    if txt == "public opinion":
        return 1
    if txt == "public opinion issue":
        return 1
    if "public opinion" in txt:
        return 1
    if "رأي عام" in txt:
        return 1

    return 0

def normalize_product_group(value):
    txt = norm(value)
    low = txt.lower()

    if txt == "مادة مكتوبة":
        return "Written"

    if txt == "مادة مرئية":
        return "Visual"

    if txt == "صور وتصاميم":
        return "Visual"

    if txt == "مادة مسموعة":
        return "Audio"

    if "written" in low or "text" in low or "article" in low:
        return "Written"

    if "visual" in low or "video" in low or "photo" in low or "image" in low or "design" in low:
        return "Visual"

    if "audio" in low or "sound" in low or "podcast" in low:
        return "Audio"

    if txt:
        return txt

    return "Unspecified"

def format_work_details(detail_map):
    parts = []
    keys = sorted(detail_map.keys())

    for key in keys:
        count_value = int(detail_map.get(key, 0))
        if count_value > 0:
            parts.append(str(key) + ": " + str(count_value))

    return "، ".join(parts)

def add_work_detail(matrix, entity_name, category_name, type_name, amount):
    safe_entity = clean_label(entity_name, "No Entity")
    safe_category = clean_label(category_name, "Other")
    safe_type = clean_label(type_name, "Unspecified")

    if safe_entity not in matrix:
        matrix[safe_entity] = {}

    entity_obj = matrix.get(safe_entity) or {}

    if safe_category not in entity_obj:
        entity_obj[safe_category] = {}

    category_obj = entity_obj.get(safe_category) or {}
    category_obj[safe_type] = int(category_obj.get(safe_type, 0)) + int(amount or 0)

    entity_obj[safe_category] = category_obj
    matrix[safe_entity] = entity_obj

def work_item_matches_date(row):
    start_date = row.get("start_date")
    end_date = row.get("end_date")

    if not start_date and not end_date:
        return 1

    if start_date and not end_date:
        start_obj = frappe.utils.getdate(start_date)
        if start_obj >= from_date_obj and start_obj <= to_date_obj:
            return 1
        return 0

    if end_date and not start_date:
        end_obj = frappe.utils.getdate(end_date)
        if end_obj >= from_date_obj and end_obj <= to_date_obj:
            return 1
        return 0

    start_obj = frappe.utils.getdate(start_date)
    end_obj = frappe.utils.getdate(end_date)

    if end_obj < from_date_obj:
        return 0

    if start_obj > to_date_obj:
        return 0

    return 1

