# Server Script Type: DocType Event
# Reference DocType: Media Plan
# Event: After Save
#
# Reflects an approved Media Plan into Project Tasks using the executing entity
# stored on every planned production/work-item row.
#
# RestrictedPython compatible:
# - no imports
# - no frappe.get_roles / frappe.has_permission / frappe.parse_json
# - no sequence unpacking
# - no dict.items()
# - no augmented assignment

TASK_DT = "Task"
WORK_ITEM_TYPE_DT = "Media Work Item Type"
UNASSIGNED_ENTITY = "Unassigned Executing Entity"

created_tasks = []
updated_tasks = []
created_assignments = []
warnings = []

current_status = str(doc.get("status") or "").strip()
current_workflow_state = str(doc.get("workflow_state") or "").strip()

is_approved = 0
if current_status == "Approved":
    is_approved = 1
if current_workflow_state == "Approved":
    is_approved = 1

if not is_approved:
    warnings.append(
        "Plan is not approved. status="
        + current_status
        + ", workflow_state="
        + current_workflow_state
    )
else:
    project = str(doc.get("project") or "").strip()
    if not project:
        frappe.throw("Media Plan must have a linked Project before tasks can be created.")
    if not frappe.db.exists("Project", project):
        frappe.throw("Linked Project does not exist: " + project)

    task_meta = frappe.get_meta(TASK_DT)
    has_is_group = 1 if task_meta.has_field("is_group") else 0
    has_start_date = 1 if task_meta.has_field("exp_start_date") else 0
    has_end_date = 1 if task_meta.has_field("exp_end_date") else 0
    has_description = 1 if task_meta.has_field("description") else 0
    has_priority = 1 if task_meta.has_field("priority") else 0

    # The requested start is the beginning of the approval day.
    approval_day = frappe.utils.today()
    reflection_start = approval_day
    if has_start_date:
        start_field = task_meta.get_field("exp_start_date")
        if start_field and start_field.fieldtype == "Datetime":
            reflection_start = str(approval_day) + " 00:00:00"

    plan_title = str(doc.get("plan_name_ar") or "").strip()
    if not plan_title:
        plan_title = str(doc.get("plan_name") or "").strip()
    if not plan_title:
        plan_title = str(doc.name)

    plan_end = doc.get("end_date")
    safe_plan_end = plan_end
    if safe_plan_end and str(safe_plan_end) < str(approval_day):
        safe_plan_end = approval_day

    plan_priority = str(doc.get("priority") or "Medium").strip()
    plan_owner = str(doc.get("plan_owner") or "").strip()
    plan_marker = "[Media Plan:" + str(doc.name) + "]"

    # Root group for this Media Plan.
    root_candidates = frappe.get_all(
        TASK_DT,
        filters={"project": project, "subject": plan_title},
        fields=["name", "parent_task", "description"],
        limit_page_length=100,
    )
    plan_task_name = ""
    for candidate in root_candidates:
        candidate_parent = str(candidate.get("parent_task") or "").strip()
        candidate_description = str(candidate.get("description") or "")
        if not candidate_parent and (
            plan_marker in candidate_description
            or "Media Plan: " + str(doc.name) in candidate_description
        ):
            plan_task_name = candidate.get("name")
            break

    if not plan_task_name:
        for candidate in root_candidates:
            if not str(candidate.get("parent_task") or "").strip():
                plan_task_name = candidate.get("name")
                break

    root_description = plan_marker + "\nGenerated from the approved Media Plan."
    if plan_task_name:
        root_doc = frappe.get_doc(TASK_DT, plan_task_name)
        root_doc.project = project
        root_doc.subject = plan_title
        if has_is_group:
            root_doc.is_group = 1
        if has_start_date:
            root_doc.exp_start_date = reflection_start
        if safe_plan_end and has_end_date:
            root_doc.exp_end_date = safe_plan_end
        if has_priority:
            root_doc.priority = plan_priority
        if has_description:
            root_doc.description = root_description
        root_doc.save(ignore_permissions=True)
        updated_tasks.append(plan_task_name)
    else:
        root_data = {
            "doctype": TASK_DT,
            "subject": plan_title,
            "project": project,
            "status": "Open",
        }
        if has_is_group:
            root_data["is_group"] = 1
        if has_start_date:
            root_data["exp_start_date"] = reflection_start
        if safe_plan_end and has_end_date:
            root_data["exp_end_date"] = safe_plan_end
        if has_priority:
            root_data["priority"] = plan_priority
        if has_description:
            root_data["description"] = root_description
        root_doc = frappe.get_doc(root_data)
        root_doc.insert(ignore_permissions=True)
        plan_task_name = root_doc.name
        created_tasks.append(plan_task_name)

    # Group production and work-item rows by the executing entity stored on each row.
    entity_order = []
    entity_seen = {}
    production_by_entity = {}
    work_items_by_entity = {}

    for production_row in doc.get("planned_production") or []:
        production_entity = str(
            production_row.get("executing_entity")
            or production_row.get("related_entity")
            or ""
        ).strip()
        if not production_entity:
            production_entity = UNASSIGNED_ENTITY
            warnings.append(
                "Media production row "
                + str(production_row.name)
                + " has no executing entity."
            )
        if production_entity not in entity_seen:
            entity_seen[production_entity] = 1
            entity_order.append(production_entity)
        if production_entity not in production_by_entity:
            production_by_entity[production_entity] = []
        production_by_entity[production_entity].append(production_row)

    for planned_item in doc.get("planned_work_items") or []:
        work_item_entity = str(
            planned_item.get("executing_entity")
            or planned_item.get("related_entity")
            or ""
        ).strip()
        if not work_item_entity:
            work_item_entity = UNASSIGNED_ENTITY
            warnings.append(
                "Media work item row "
                + str(planned_item.name)
                + " has no executing entity."
            )
        if work_item_entity not in entity_seen:
            entity_seen[work_item_entity] = 1
            entity_order.append(work_item_entity)
        if work_item_entity not in work_items_by_entity:
            work_items_by_entity[work_item_entity] = []
        work_items_by_entity[work_item_entity].append(planned_item)

    if len(entity_order) == 0:
        warnings.append("The approved Media Plan has no production or work-item rows.")

    # Load work-item categories once.
    work_type_category = {}
    if frappe.db.exists("DocType", WORK_ITEM_TYPE_DT):
        work_type_meta = frappe.get_meta(WORK_ITEM_TYPE_DT)
        if work_type_meta.has_field("category"):
            work_type_rows = frappe.get_all(
                WORK_ITEM_TYPE_DT,
                fields=["name", "category"],
                limit_page_length=0,
            )
            for type_row in work_type_rows:
                type_name = str(type_row.get("name") or "").strip()
                category_name = str(type_row.get("category") or "Other").strip()
                if type_name:
                    work_type_category[type_name] = category_name or "Other"

    for entity_name in entity_order:
        # Executing entity group.
        entity_task_name = frappe.db.exists(
            TASK_DT,
            {
                "project": project,
                "parent_task": plan_task_name,
                "subject": entity_name,
            },
        )
        entity_description = (
            plan_marker + "\nExecuting entity: " + str(entity_name)
        )
        if entity_task_name:
            entity_doc = frappe.get_doc(TASK_DT, entity_task_name)
            if has_is_group:
                entity_doc.is_group = 1
            if has_start_date:
                entity_doc.exp_start_date = reflection_start
            if safe_plan_end and has_end_date:
                entity_doc.exp_end_date = safe_plan_end
            if has_description:
                entity_doc.description = entity_description
            entity_doc.save(ignore_permissions=True)
            updated_tasks.append(entity_task_name)
        else:
            entity_data = {
                "doctype": TASK_DT,
                "subject": entity_name,
                "project": project,
                "parent_task": plan_task_name,
                "status": "Open",
            }
            if has_is_group:
                entity_data["is_group"] = 1
            if has_start_date:
                entity_data["exp_start_date"] = reflection_start
            if safe_plan_end and has_end_date:
                entity_data["exp_end_date"] = safe_plan_end
            if has_description:
                entity_data["description"] = entity_description
            entity_doc = frappe.get_doc(entity_data)
            entity_doc.insert(ignore_permissions=True)
            entity_task_name = entity_doc.name
            created_tasks.append(entity_task_name)

        entity_production_rows = production_by_entity.get(entity_name) or []
        if len(entity_production_rows) > 0:
            # Media Production group only for entities that have production rows.
            production_subject = "Media Production"
            production_task_name = frappe.db.exists(
                TASK_DT,
                {
                    "project": project,
                    "parent_task": entity_task_name,
                    "subject": production_subject,
                },
            )
            if production_task_name:
                production_doc = frappe.get_doc(TASK_DT, production_task_name)
                if has_is_group:
                    production_doc.is_group = 1
                if has_start_date:
                    production_doc.exp_start_date = reflection_start
                if safe_plan_end and has_end_date:
                    production_doc.exp_end_date = safe_plan_end
                production_doc.save(ignore_permissions=True)
                updated_tasks.append(production_task_name)
            else:
                production_data = {
                    "doctype": TASK_DT,
                    "subject": production_subject,
                    "project": project,
                    "parent_task": entity_task_name,
                    "status": "Open",
                }
                if has_is_group:
                    production_data["is_group"] = 1
                if has_start_date:
                    production_data["exp_start_date"] = reflection_start
                if safe_plan_end and has_end_date:
                    production_data["exp_end_date"] = safe_plan_end
                production_doc = frappe.get_doc(production_data)
                production_doc.insert(ignore_permissions=True)
                production_task_name = production_doc.name
                created_tasks.append(production_task_name)

            material_type_task_names = {}
            for production_row in entity_production_rows:
                material_type = str(
                    production_row.get("material_type") or "Other"
                ).strip()
                if not material_type:
                    material_type = "Other"

                material_type_task_name = material_type_task_names.get(material_type)
                if not material_type_task_name:
                    material_type_task_name = frappe.db.exists(
                        TASK_DT,
                        {
                            "project": project,
                            "parent_task": production_task_name,
                            "subject": material_type,
                        },
                    )
                    if material_type_task_name:
                        material_type_doc = frappe.get_doc(
                            TASK_DT, material_type_task_name
                        )
                        if has_is_group:
                            material_type_doc.is_group = 1
                        if has_start_date:
                            material_type_doc.exp_start_date = reflection_start
                        if safe_plan_end and has_end_date:
                            material_type_doc.exp_end_date = safe_plan_end
                        material_type_doc.save(ignore_permissions=True)
                        updated_tasks.append(material_type_task_name)
                    else:
                        material_type_data = {
                            "doctype": TASK_DT,
                            "subject": material_type,
                            "project": project,
                            "parent_task": production_task_name,
                            "status": "Open",
                        }
                        if has_is_group:
                            material_type_data["is_group"] = 1
                        if has_start_date:
                            material_type_data["exp_start_date"] = reflection_start
                        if safe_plan_end and has_end_date:
                            material_type_data["exp_end_date"] = safe_plan_end
                        material_type_doc = frappe.get_doc(material_type_data)
                        material_type_doc.insert(ignore_permissions=True)
                        material_type_task_name = material_type_doc.name
                        created_tasks.append(material_type_task_name)
                    material_type_task_names[material_type] = material_type_task_name

                material = str(production_row.get("material") or "").strip()
                material_name = str(
                    production_row.get("material_name") or material or material_type
                ).strip()
                planned_quantity = int(
                    production_row.get("planned_quantity") or 0
                )
                production_subject_text = material_name
                if planned_quantity > 0:
                    production_subject_text = (
                        production_subject_text
                        + " × "
                        + str(planned_quantity)
                    )

                production_marker = (
                    "[Media Plan Production:" + str(production_row.name) + "]"
                )
                production_leaf_rows = frappe.get_all(
                    TASK_DT,
                    filters={
                        "project": project,
                        "description": ["like", "%" + production_marker + "%"],
                    },
                    fields=["name"],
                    limit_page_length=2,
                )
                production_leaf_name = ""
                if len(production_leaf_rows) > 0:
                    production_leaf_name = production_leaf_rows[0].get("name")
                if not production_leaf_name:
                    production_leaf_name = frappe.db.exists(
                        TASK_DT,
                        {
                            "project": project,
