# Server Script Type: DocType Event
# Reference DocType: Media Production Test
# Event: After Save
#
# For production_source = Planned, creates a real Task for every Started item:
# Project > Media Plan > Executing Department > Media Production
#         > Material Type (Group) > Item Title (Task)
#
# RestrictedPython compatible: no imports, no helper functions, no +=, no clear_cache.

TASK_DT = "Task"

created_tasks = []
updated_tasks = []
created_assignments = []
skipped = []

production_source = str(doc.get("production_source") or "").strip()
media_plan_name = str(doc.get("media_plan") or "").strip()

if production_source != "Planned":
    skipped.append("Production Source is not Planned.")
elif not media_plan_name:
    frappe.throw("Planned Media Production must be linked to a Media Plan.")
elif not frappe.db.exists("Media Plan", media_plan_name):
    frappe.throw("Linked Media Plan does not exist: " + media_plan_name)
else:
    media_plan_doc = frappe.get_doc("Media Plan", media_plan_name)
    project = str(media_plan_doc.get("project") or "").strip()

    if not project:
        frappe.throw("Linked Media Plan must have a Project.")
    if not frappe.db.exists("Project", project):
        frappe.throw("Project does not exist: " + project)

    # Exactly one Executing Department must exist on Media Production Test.
    executing_entities = []
    executing_seen = {}
    for relation in (doc.get("related_entities") or []):
        entity_role = str(relation.get("entity_role") or "").strip()
        entity_name = str(relation.get("entity") or "").strip()
        if entity_role == "Executing Department" and entity_name and entity_name not in executing_seen:
            executing_entities.append(entity_name)
            executing_seen[entity_name] = 1

    if len(executing_entities) == 0:
        frappe.throw("Media Production Test must contain one Executing Department in Related Entities.")
    if len(executing_entities) > 1:
        frappe.throw("Media Production Test must contain only one Executing Department.")

    executing_entity = executing_entities[0]

    # Verify that the same department exists in the Media Plan.
    plan_entity_match = 0
    for plan_relation in (media_plan_doc.get("related_entities") or []):
        plan_role = str(plan_relation.get("entity_role") or "").strip()
        plan_entity = str(plan_relation.get("entity") or "").strip()
        if plan_role == "Executing Department" and plan_entity == executing_entity:
            plan_entity_match = 1
            break

    if not plan_entity_match:
        frappe.throw("Executing Department in Media Production does not match the linked Media Plan: " + executing_entity)

    task_meta = frappe.get_meta(TASK_DT)
    has_is_group = 1 if task_meta.has_field("is_group") else 0
    has_start_date = 1 if task_meta.has_field("exp_start_date") else 0
    has_end_date = 1 if task_meta.has_field("exp_end_date") else 0
    has_description = 1 if task_meta.has_field("description") else 0
    has_priority = 1 if task_meta.has_field("priority") else 0

    plan_title = str(media_plan_doc.get("plan_name_ar") or "").strip()
    if not plan_title:
        plan_title = str(media_plan_doc.get("plan_name") or "").strip()
    if not plan_title:
        plan_title = media_plan_name

    plan_start = media_plan_doc.get("start_date")
    plan_end = media_plan_doc.get("end_date")
    plan_priority = str(media_plan_doc.get("priority") or "Medium").strip()

    # Locate the existing plan root group.
    plan_task_name = ""
    plan_candidates = frappe.get_all(
        TASK_DT,
        filters={"project": project, "subject": plan_title},
        fields=["name", "parent_task"],
        limit_page_length=100
    )
    for candidate in plan_candidates:
        if not str(candidate.get("parent_task") or "").strip():
            plan_task_name = candidate.get("name")
            break

    if not plan_task_name:
        frappe.throw("Media Plan group task was not found in the linked Project. Approve/save the Media Plan first.")

    # Locate the department group.
    entity_task_name = frappe.db.exists(
        TASK_DT,
        {"project": project, "parent_task": plan_task_name, "subject": executing_entity}
    )
    if not entity_task_name:
        frappe.throw("Executing Department group task was not found under the Media Plan: " + executing_entity)

    # Locate or create Media Production group.
    production_group_subject = "Media Production"
    production_group_name = frappe.db.exists(
        TASK_DT,
        {"project": project, "parent_task": entity_task_name, "subject": production_group_subject}
    )
    if not production_group_name:
        production_group_data = {
            "doctype": TASK_DT,
            "subject": production_group_subject,
            "project": project,
            "parent_task": entity_task_name,
            "status": "Open"
        }
        if has_is_group:
            production_group_data["is_group"] = 1
        if plan_start and has_start_date:
            production_group_data["exp_start_date"] = plan_start
        if plan_end and has_end_date:
            production_group_data["exp_end_date"] = plan_end
        if has_description:
            production_group_data["description"] = "Media Production for Media Plan: " + media_plan_name
        production_group_doc = frappe.get_doc(production_group_data)
        production_group_doc.insert(ignore_permissions=True)
        production_group_name = production_group_doc.name
        created_tasks.append(production_group_name)

    started_items_count = 0

    for item in (doc.get("items") or []):
        item_status = str(item.get("item_status") or "").strip()

        # Create the task when the item reaches Started.
        if item_status != "Started":
            continue

        started_items_count = started_items_count + 1

        material_type = str(item.get("material_type") or "").strip()
        if not material_type:
            skipped.append("Item row " + str(item.get("idx") or "") + " has no Material Type.")
            continue

        item_title = str(item.get("item_title") or "").strip()
        if not item_title:
            item_title = str(doc.get("request_title") or "Media Production Item").strip()
            item_title = item_title + " - " + material_type + " - " + str(item.get("idx") or "")

        item_start = item.get("start_date") or item.get("production_date") or doc.get("request_date") or plan_start
        item_end = item.get("end_date") or doc.get("requested_completion_date") or plan_end
        responsible = str(item.get("responsible") or "").strip()

        # Create the missing material branch even when it was not planned.
        material_group_name = frappe.db.exists(
            TASK_DT,
            {"project": project, "parent_task": production_group_name, "subject": material_type}
        )
        if not material_group_name:
            material_group_data = {
                "doctype": TASK_DT,
                "subject": material_type,
                "project": project,
                "parent_task": production_group_name,
                "status": "Open"
            }
            if has_is_group:
                material_group_data["is_group"] = 1
            if item_start and has_start_date:
                material_group_data["exp_start_date"] = item_start
            elif plan_start and has_start_date:
                material_group_data["exp_start_date"] = plan_start
            if item_end and has_end_date:
                material_group_data["exp_end_date"] = item_end
            elif plan_end and has_end_date:
                material_group_data["exp_end_date"] = plan_end
            if has_description:
                material_group_data["description"] = "Automatically created for an unplanned or newly required material type."
            material_group_doc = frappe.get_doc(material_group_data)
            material_group_doc.insert(ignore_permissions=True)
            material_group_name = material_group_doc.name
            created_tasks.append(material_group_name)

        # A subject is unique within its material branch for this reflection.
        item_task_name = frappe.db.exists(
            TASK_DT,
            {"project": project, "parent_task": material_group_name, "subject": item_title}
        )

        task_description = "Generated from Media Production Test: " + str(doc.name)
        task_description = task_description + " | Item row: " + str(item.get("idx") or "")
        if item.get("notes"):
            task_description = task_description + "\n" + str(item.get("notes"))

        if item_task_name:
            item_task_doc = frappe.get_doc(TASK_DT, item_task_name)
            item_task_doc.project = project
            item_task_doc.parent_task = material_group_name
            item_task_doc.status = "Open"
            if has_is_group:
                item_task_doc.is_group = 0
            if item_start and has_start_date:
                item_task_doc.exp_start_date = item_start
            if item_end and has_end_date:
                item_task_doc.exp_end_date = item_end
            if has_priority:
                item_task_doc.priority = plan_priority
            if has_description:
                item_task_doc.description = task_description
            item_task_doc.save(ignore_permissions=True)
            updated_tasks.append(item_task_name)
        else:
            item_task_data = {
                "doctype": TASK_DT,
                "subject": item_title,
                "project": project,
                "parent_task": material_group_name,
                "status": "Open"
            }
            if has_is_group:
                item_task_data["is_group"] = 0
            if item_start and has_start_date:
                item_task_data["exp_start_date"] = item_start
            if item_end and has_end_date:
                item_task_data["exp_end_date"] = item_end
            if has_priority:
                item_task_data["priority"] = plan_priority
            if has_description:
                item_task_data["description"] = task_description
            item_task_doc = frappe.get_doc(item_task_data)
            item_task_doc.insert(ignore_permissions=True)
            item_task_name = item_task_doc.name
            created_tasks.append(item_task_name)

        if item.get("name") and str(item.get("related_task") or "").strip() != item_task_name:
            frappe.db.set_value("Media Production Test Item", item.get("name"), "related_task", item_task_name, update_modified=False)

        # Assign the real task to Media Production Test Item.responsible.
        if responsible:
            if not frappe.db.exists("User", responsible):
                skipped.append("Responsible user does not exist: " + responsible)
            else:
                assignment_name = frappe.db.exists(
                    "ToDo",
                    {
                        "reference_type": TASK_DT,
                        "reference_name": item_task_name,
                        "allocated_to": responsible,
                        "status": "Open"
                    }
                )
                if not assignment_name:
                    assignment_doc = frappe.get_doc({
                        "doctype": "ToDo",
                        "allocated_to": responsible,
                        "reference_type": TASK_DT,
                        "reference_name": item_task_name,
                        "description": item_title,
                        "status": "Open",
                        "priority": plan_priority
                    })
                    assignment_doc.insert(ignore_permissions=True)
                    created_assignments.append(assignment_doc.name)
        else:
            skipped.append("Started item has no Responsible user: " + item_title)

    if started_items_count == 0:
        skipped.append("No item with Item Status = Started.")

frappe.response["message"] = {
    "success": True,
    "media_production": doc.name,
    "production_source": production_source,
    "media_plan": media_plan_name,
    "created_tasks_count": len(created_tasks),
    "updated_tasks_count": len(updated_tasks),
    "created_assignments_count": len(created_assignments),
    "created_tasks": created_tasks,
    "updated_tasks": updated_tasks,
    "created_assignments": created_assignments,
    "skipped": skipped
}

