    if not entity_matches_plan:
        frappe.throw("Work Item entity does not match an Executing Department in the linked Media Plan: " + entity)

    category = str(frappe.db.get_value(WORK_ITEM_TYPE_DT, work_item_type, "category") or "Other").strip()
    if not category:
