    task_meta = frappe.get_meta(TASK_DT)
    has_is_group = 1 if task_meta.has_field("is_group") else 0
    has_start_date = 1 if task_meta.has_field("exp_start_date") else 0
    has_end_date = 1 if task_meta.has_field("exp_end_date") else 0
    has_description = 1 if task_meta.has_field("description") else 0
    has_priority = 1 if task_meta.has_field("priority") else 0

    plan_title = str(media_plan_doc.get("plan_name_ar") or "").strip()
    if not plan_title:
        plan_title = str(media_plan_doc.get("plan_name") or "").strip()
    if not plan_title:
        plan_title = media_plan_name

    plan_start = media_plan_doc.get("start_date")
    plan_end = media_plan_doc.get("end_date")
    item_start = doc.get("start_date") or plan_start
    item_end = doc.get("end_date") or plan_end
    item_priority = str(doc.get("priority") or media_plan_doc.get("priority") or "Medium").strip()
    item_title = str(doc.get("work_item_title") or "").strip()
    if not item_title:
        item_title = str(frappe.db.get_value(WORK_ITEM_TYPE_DT, work_item_type, "type_name_ar") or "").strip()
    if not item_title:
        item_title = str(frappe.db.get_value(WORK_ITEM_TYPE_DT, work_item_type, "type_name") or "").strip()
    if not item_title:
        item_title = work_item_type

    # Locate Media Plan root group.
    plan_task_name = ""
    plan_candidates = frappe.get_all(
        TASK_DT,
        filters={"project": project, "subject": plan_title},
        fields=["name", "parent_task"],
        limit_page_length=100
    )
    for candidate in plan_candidates:
        if not str(candidate.get("parent_task") or "").strip():
            plan_task_name = candidate.get("name")
            break

    if not plan_task_name:
        frappe.throw("Media Plan group task was not found in the Project. Approve/save the Media Plan first.")

    # Locate executing department group.
    entity_task_name = frappe.db.exists(
        TASK_DT,
        {"project": project, "parent_task": plan_task_name, "subject": entity}
    )
    if not entity_task_name:
        frappe.throw("Executing Department group task was not found under the Media Plan: " + entity)

    # Locate or create Work Items group.
    work_group_subject = "Work Items"
    work_group_name = frappe.db.exists(
        TASK_DT,
        {"project": project, "parent_task": entity_task_name, "subject": work_group_subject}
