        elif plan_start and has_start_date:
            category_group_data["exp_start_date"] = plan_start
        if item_end and has_end_date:
            category_group_data["exp_end_date"] = item_end
        elif plan_end and has_end_date:
            category_group_data["exp_end_date"] = plan_end
        if has_description:
            category_group_data["description"] = "Work Item category from Media Work Item Type: " + work_item_type
        category_group_doc = frappe.get_doc(category_group_data)
        category_group_doc.insert(ignore_permissions=True)
        category_group_name = category_group_doc.name
        created_tasks.append(category_group_name)

    # Prefer the explicit Task link. Fall back to hierarchy lookup.
    task_name = str(doc.get("related_task") or "").strip()
    if task_name and not frappe.db.exists(TASK_DT, task_name):
        task_name = ""

    if not task_name:
        task_name = frappe.db.exists(
            TASK_DT,
            {"project": project, "parent_task": category_group_name, "subject": item_title}
        )

    task_description = "Generated/updated from Media Work Item: " + str(doc.name)
    if doc.get("description"):
        task_description = task_description + "\n" + str(doc.get("description"))
    elif doc.get("expected_output"):
        task_description = task_description + "\nExpected Output: " + str(doc.get("expected_output"))
    elif doc.get("notes"):
        task_description = task_description + "\n" + str(doc.get("notes"))

    if task_name:
