        task_doc.subject = item_title
        task_doc.project = project
        task_doc.parent_task = category_group_name
        task_doc.status = "Open"
        if has_is_group:
            task_doc.is_group = 0
        if item_start and has_start_date:
            task_doc.exp_start_date = item_start
        if item_end and has_end_date:
            task_doc.exp_end_date = item_end
        if has_priority:
            task_doc.priority = item_priority
        if has_description:
            task_doc.description = task_description
        task_doc.save(ignore_permissions=True)
        updated_tasks.append(task_name)
    else:
        task_data = {
            "doctype": TASK_DT,
            "subject": item_title,
            "project": project,
            "parent_task": category_group_name,
            "status": "Open"
        }
        if has_is_group:
            task_data["is_group"] = 0
        if item_start and has_start_date:
            task_data["exp_start_date"] = item_start
        if item_end and has_end_date:
            task_data["exp_end_date"] = item_end
        if has_priority:
            task_data["priority"] = item_priority
        if has_description:
            task_data["description"] = task_description
        task_doc = frappe.get_doc(task_data)
        task_doc.insert(ignore_permissions=True)
        task_name = task_doc.name
        created_tasks.append(task_name)

    # Save the Task link without calling Media Work Item.save() again.
    if str(doc.get("related_task") or "").strip() != task_name:
        frappe.db.set_value("Media Work Item", doc.name, "related_task", task_name, update_modified=False)

    # Add assigned_user only when the task has no open assignment at all.
    open_assignments = frappe.get_all(
        "ToDo",
        filters={"reference_type": TASK_DT, "reference_name": task_name, "status": "Open"},
        fields=["name", "allocated_to"],
        limit_page_length=100
    )

    if len(open_assignments) == 0:
        if assigned_user:
            if not frappe.db.exists("User", assigned_user):
                skipped.append("Assigned User does not exist: " + assigned_user)
            else:
                assignment_doc = frappe.get_doc({
                    "doctype": "ToDo",
                    "allocated_to": assigned_user,
                    "reference_type": TASK_DT,
                    "reference_name": task_name,
                    "description": item_title,
                    "status": "Open",
                    "priority": item_priority
                })
                assignment_doc.insert(ignore_permissions=True)
                created_assignments.append(assignment_doc.name)
        else:
            skipped.append("Started Work Item has no Assigned User.")
    else:
        skipped.append("Task already has an open assignment; assigned_user was not added again.")

frappe.response["message"] = {
    "success": True,
    "media_work_item": doc.name,
    "execution_source": execution_source,
    "status": work_status,
    "media_plan": media_plan_name,
    "created_tasks_count": len(created_tasks),
    "updated_tasks_count": len(updated_tasks),
    "created_assignments_count": len(created_assignments),
    "created_tasks": created_tasks,
    "updated_tasks": updated_tasks,
    "created_assignments": created_assignments,
    "skipped": skipped
}

# Server Script Type: DocType Event
# Reference DocType: Media Work Item
# Event: After Save
#
# Handles execution_source = Unplanned or Urgent when status = Started.
#
# Hierarchy:
# Project
# `-- Executing Department (Group)
#     `-- Unplanned/Urgent Group (Group)
#         `-- Work Item Category (Group)
#             `-- Work Item (real Task + assignment)
#
# RestrictedPython compatible: no imports, no helper functions, no +=, no clear_cache.

TASK_DT = "Task"
SETTINGS_DT = "Media Task Routing Settings"
WORK_ITEM_TYPE_DT = "Media Work Item Type"

created_tasks = []
updated_tasks = []
created_assignments = []
skipped = []

execution_source = str(doc.get("execution_source") or "").strip()
work_status = str(doc.get("status") or "").strip()

if execution_source == "Planned":
    skipped.append("Execution Source is Planned; this script handles Unplanned and Urgent work only.")
elif execution_source not in ["Unplanned", "Urgent"]:
    skipped.append("Execution Source is neither Unplanned nor Urgent.")
elif work_status != "Started":
