    has_end_date = 1 if task_meta.has_field("exp_end_date") else 0
    has_description = 1 if task_meta.has_field("description") else 0
    has_priority = 1 if task_meta.has_field("priority") else 0

    item_start = doc.get("start_date")
    item_end = doc.get("end_date")
    item_priority = str(doc.get("priority") or "Medium").strip()
    if route_kind == "Urgent" and item_priority in ["Low", "Medium"]:
        item_priority = "High"

    item_title = str(doc.get("work_item_title") or "").strip()
    if not item_title:
        item_title = str(frappe.db.get_value(WORK_ITEM_TYPE_DT, work_item_type, "type_name_ar") or "").strip()
    if not item_title:
        item_title = str(frappe.db.get_value(WORK_ITEM_TYPE_DT, work_item_type, "type_name") or "").strip()
    if not item_title:
        item_title = work_item_type

    # Executing Department is always the top-level group under Project.
    entity_task_name = ""
    entity_candidates = frappe.get_all(
