        source_group_doc.insert(ignore_permissions=True)
        source_group_task_name = source_group_doc.name
        created_tasks.append(source_group_task_name)

    # Work Item category group under source group.
    category_group_name = frappe.db.exists(
        TASK_DT,
        {"project": project, "parent_task": source_group_task_name, "subject": category}
    )
