        task_doc.project = project
        task_doc.parent_task = category_group_name
        task_doc.status = "Open"
        if has_is_group:
            task_doc.is_group = 0
        if item_start and has_start_date:
            task_doc.exp_start_date = item_start
        if item_end and has_end_date:
            task_doc.exp_end_date = item_end
        if has_priority:
            task_doc.priority = item_priority
        if has_description:
            task_doc.description = task_description
        task_doc.save(ignore_permissions=True)
        updated_tasks.append(task_name)
    else:
