# Server Script Type: DocType Event
# Reference DocType: Media Work Item
# Event: After Save
#
# Synchronizes Media Work Item fields to related_task.
# RestrictedPython compatible: no imports, no helper functions, no +=, no clear_cache.

TASK_DT = "Task"

updated_task = ""
created_assignment = ""
skipped = []

task_name = str(doc.get("related_task") or "").strip()

if not task_name:
