    if source_status == "In Progress":
        task_status = "Working"
    elif source_status in ["Completed", "Approved"]:
        task_status = "Completed"
    elif source_status == "Cancelled":
        task_status = "Cancelled"
    elif source_status in ["Draft", "Started"]:
        task_status = "Open"

    progress_value = float(doc.get("progress") or 0)
    if progress_value < 0:
        progress_value = 0
    if progress_value > 100:
        progress_value = 100
    if source_status in ["Completed", "Approved"]:
        progress_value = 100

