            description_value = description_value + "\nExpected Output: " + str(doc.get("expected_output"))
        elif doc.get("notes"):
            description_value = description_value + "\n" + str(doc.get("notes"))
        task_doc.description = description_value

    task_doc.save(ignore_permissions=True)
    updated_task = task_name

    assigned_user = str(doc.get("assigned_user") or "").strip()
    if assigned_user:
        if not frappe.db.exists("User", assigned_user):
            skipped.append("Assigned User does not exist: " + assigned_user)
        else:
            user_assignment = frappe.db.exists(
                "ToDo",
                {
                    "reference_type": TASK_DT,
