def ensure_child_doctype(doctype_name, field_specs):
    if frappe.db.exists("DocType", doctype_name):
        is_custom = frappe.db.get_value("DocType", doctype_name, "custom")
        if not is_custom:
            frappe.db.set_value("DocType", doctype_name, "custom", 1, update_modified=False)
            result["warnings"].append("Repaired existing DocType as Custom: " + doctype_name)
        result["existing_items"].append("DocType: " + doctype_name)
        return
    doc = frappe.get_doc({
        "doctype": "DocType",
        "name": doctype_name,
        "module": "MOI",
        "custom": 1,
        "istable": 1,
        "editable_grid": 1,
        "fields": field_specs
    })
    doc.insert(ignore_permissions=True)
    result["created_doctypes"].append(doctype_name)

def ensure_custom_field(parent_doctype, spec):
    fieldname = spec.get("fieldname")
    existing_name = frappe.db.get_value("Custom Field", {"dt": parent_doctype, "fieldname": fieldname}, "name")
    if existing_name:
        existing = frappe.get_doc("Custom Field", existing_name)
        changed = False
        for key in ["label", "fieldtype", "options", "default", "reqd", "hidden", "in_list_view", "insert_after"]:
            expected = spec.get(key) or ""
            actual = existing.get(key)
            if str(actual or "") != str(expected or ""):
                existing.set(key, expected)
                changed = True
        if changed:
            existing.save(ignore_permissions=True)
            result["updated_fields"].append(parent_doctype + "." + fieldname)
        else:
            result["existing_items"].append("Field: " + parent_doctype + "." + fieldname)
        return
    native_field = frappe.get_meta(parent_doctype).get_field(fieldname)
    if native_field:
        native_mismatches = []
        for key in ["label", "fieldtype", "options", "default", "reqd", "hidden", "in_list_view"]:
            expected = spec.get(key)
            actual = native_field.get(key)
            if str(actual or "") != str(expected or ""):
                native_mismatches.append(key)
        if native_mismatches:
            result["warnings"].append(parent_doctype + "." + fieldname + " native field differs in: " + ", ".join(native_mismatches))
        else:
            result["existing_items"].append("Native field: " + parent_doctype + "." + fieldname)
        return
    field_doc = frappe.get_doc({
        "doctype": "Custom Field",
        "dt": parent_doctype,
        "label": spec.get("label"),
        "fieldname": fieldname,
        "fieldtype": spec.get("fieldtype"),
        "options": spec.get("options"),
        "default": spec.get("default"),
        "reqd": spec.get("reqd") or 0,
        "hidden": spec.get("hidden") or 0,
        "in_list_view": spec.get("in_list_view") or 0,
        "insert_after": spec.get("insert_after")
    })
    field_doc.insert(ignore_permissions=True)
    result["created_fields"].append(parent_doctype + "." + fieldname)

