def patch_api_script(api_method, replacements):
    server_script_name = frappe.db.get_value("Server Script", {"api_method": api_method}, "name")
    if not server_script_name:
        result["warnings"].append("Server Script not found: " + api_method)
        return
    server_script = frappe.get_doc("Server Script", server_script_name)
    source = server_script.get("script") or ""
    updated = source
    for replacement in replacements:
        old_text = replacement[0]
        new_text = replacement[1]
        if new_text not in updated:
            updated = updated.replace(old_text, new_text)
    if updated != source:
        server_script.set("script", updated)
        server_script.save(ignore_permissions=True)
        result["updated_fields"].append("Server Script: " + api_method)
    else:
        result["existing_items"].append("Server Script: " + api_method)

