def clean(value, maximum):
    return str(value or "").strip()[0:maximum]

def safe_public_text(value):
    text = str(value or "")
    text = text.replace("&lt;", "<").replace("&gt;", ">")
    text = text.replace("&quot;", '\"').replace("&#39;", "'")
    plain = ""
    inside_tag = False
    for character in text:
        if character == "<":
            inside_tag = True
        elif character == ">":
            inside_tag = False
            plain = plain + " "
        elif not inside_tag:
            plain = plain + character
    plain = plain.replace("&nbsp;", " ").replace("&amp;", " ")
    return " ".join(plain.split())

