        errors.append({"sheet": sheet_names.get(table_fieldname), "row": 0, "fieldname": table_fieldname, "message": "Sheet data must be a list"})
        clean_payload[table_fieldname] = clean_rows
        continue
    child_meta = frappe.get_meta(table_df.options)
    allowed = {}
    for df in child_meta.fields:
        if df.fieldname and not df.hidden and not df.read_only and df.fieldtype not in ["Section Break", "Column Break", "Tab Break", "HTML", "Button", "Table", "Table MultiSelect"]:
            allowed[df.fieldname] = df
    row_number = 2
    for source_row in rows:
        row_number = row_number + 1
        if not isinstance(source_row, dict):
            errors.append({"sheet": sheet_names.get(table_fieldname), "row": row_number, "fieldname": "", "message": "Row must be an object"})
            continue
        clean_row = {}
        for supplied_field in source_row:
            if supplied_field not in allowed and supplied_field != "_source_row":
                errors.append({"sheet": sheet_names.get(table_fieldname), "row": row_number, "fieldname": supplied_field, "message": "Unknown field"})
        for fieldname in allowed:
            df = allowed.get(fieldname)
            value = source_row.get(fieldname)
            if isinstance(value, str):
                value = value.strip()
            if value is None or value == "":
                if df.reqd:
                    errors.append({"sheet": sheet_names.get(table_fieldname), "row": row_number, "fieldname": fieldname, "message": "Required value is missing"})
                continue
            if df.fieldtype == "Select":
                options = [option.strip() for option in str(df.options or "").split("\n") if option.strip()]
                if value not in options:
                    errors.append({"sheet": sheet_names.get(table_fieldname), "row": row_number, "fieldname": fieldname, "message": "Invalid Select value"})
            if df.fieldtype == "Link" and not frappe.db.exists(df.options, value):
                errors.append({"sheet": sheet_names.get(table_fieldname), "row": row_number, "fieldname": fieldname, "message": "Linked record does not exist: " + str(value)})
            if df.fieldtype in ["Int", "Float", "Currency", "Percent"]:
                try:
                    value = frappe.utils.flt(value) if df.fieldtype != "Int" else frappe.utils.cint(value)
                except Exception:
                    errors.append({"sheet": sheet_names.get(table_fieldname), "row": row_number, "fieldname": fieldname, "message": "Invalid numeric value"})
            clean_row[fieldname] = value
        if clean_row:
            if table_fieldname in duplicate_trackers:
                link_df = None
                for fieldname in allowed:
                    if allowed.get(fieldname).fieldtype == "Link":
                        link_df = allowed.get(fieldname)
                        break
                if link_df and clean_row.get(link_df.fieldname):
                    duplicate_value = str(clean_row.get(link_df.fieldname))
                    tracker = duplicate_trackers.get(table_fieldname)
                    if tracker.get(duplicate_value):
                        errors.append({"sheet": sheet_names.get(table_fieldname), "row": row_number, "fieldname": link_df.fieldname, "message": "Duplicate linked value"})
                    tracker[duplicate_value] = True
