# Interview Report Export
# ERPNext 15 Server Script API


interviews = frappe.get_all(
    "Interview",
    fields=[
        "name",
        "job_applicant",
        "status",
        "interview_round"
    ]
)


cleared = []
rejected = []


for row in interviews:

    doc = frappe.get_doc(
        "Interview",
        row.name
    )


    weights = {}

    for member in doc.committee_members:

        weights[member.member_type] = float(
            member.weight or 0
        )


    member_result = {}


    for ev in doc.member_evaluations:

        if not ev.max_score:
            continue


        member = ev.committee_member


        if member not in member_result:

            member_result[member] = {
                "score": 0,
                "max": 0
            }


        member_result[member]["score"] = (
            member_result[member]["score"]
            +
            (ev.score or 0)
        )


        member_result[member]["max"] = (
            member_result[member]["max"]
            +
            (ev.max_score or 0)
        )


    categories = {}


    for member in member_result:

        values = member_result[member]


        if values["max"] == 0:
            continue


        percent = (
            values["score"]
            /
            values["max"]
        ) * 100


        member_type = ""


        for c in doc.committee_members:

            if c.member == member:

                member_type = c.member_type
                break


        if member_type not in categories:

            categories[member_type] = []


        categories[member_type].append(
            percent
        )


    final_categories = {}


    for category in categories:

        total = 0

        for value in categories[category]:

            total = total + value


        final_categories[category] = (
            total / len(categories[category])
        )


    final_score = 0


    for category in final_categories:

        final_score = (
            final_score
            +
            (
                final_categories[category]
                *
                weights.get(category, 0)
                /
                100
            )
        )


    applicant_name = ""


    if row.job_applicant:

        applicant_name = frappe.db.get_value(
            "Job Applicant",
            row.job_applicant,
            "applicant_name"
        )


    line = [

        applicant_name,

        round(
            final_categories.get("HR",0),
            2
        ),

        round(
            final_categories.get("إداري",0),
            2
        ),

        round(
            final_categories.get("فني",0),
            2
        ),

        round(
            final_score,
            2
        ),

        row.status

    ]


    if row.status == "Cleared":

        cleared.append(line)


    elif row.status == "Rejected":

        rejected.append(line)



