    executing_role_fieldname = None
    for child_df in child_meta.fields:
        include_hidden_reference = table_fieldname == "goal_audience_distribution" and child_df.fieldname == "goal_reference"
        if child_df.fieldname and (not child_df.hidden or include_hidden_reference) and not child_df.read_only and child_df.fieldtype not in ["Section Break", "Column Break", "Tab Break", "HTML", "Button", "Table", "Table MultiSelect"]:
            allowed[child_df.fieldname] = child_df
            if child_df.reqd:
