            if table_fieldname == "related_entities" and child_df.fieldtype == "Select" and "Executing Department" in str(child_df.options or ""):
                executing_role_fieldname = child_df.fieldname
    seen_links = {}
    for row in rows:
        if not isinstance(row, dict):
            frappe.throw("Every row in " + table_fieldname + " must be an object.")
        if table_fieldname == "goal_audience_distribution":
            selected_value = row.get("selected")
            if selected_value in [0, "0", False, "false", "False"]:
                continue
        clean = {}
        for supplied_field in row:
            if supplied_field not in allowed and supplied_field not in ["_rowId", "_source_row", "_materialRequest", "_ref"]:
                frappe.throw("Unknown field in " + table_fieldname + ": " + supplied_field)
        for fieldname in allowed:
            df = allowed.get(fieldname)
            value = row.get(fieldname)
            if value is None or value == "":
                continue
            if isinstance(value, str):
                value = value.strip()
            if df.fieldtype == "Select":
                options = [option.strip() for option in str(df.options or "").split("\n") if option.strip()]
                if value not in options:
                    frappe.throw("Invalid Select value for " + table_fieldname + "." + fieldname)
            if df.fieldtype == "Link" and not frappe.db.exists(df.options, value):
                frappe.throw("Linked record does not exist for " + table_fieldname + "." + fieldname + ": " + str(value))
            if df.fieldtype in ["Int", "Float", "Currency", "Percent"]:
                if table_fieldname == "goal_audience_distribution" and fieldname == "allocation_percentage":
                    percentage_text = str(value).strip()
