                        break
                if first_link and clean.get(first_link):
                    link_value = str(clean.get(first_link))
                    if seen_links.get(link_value):
                        frappe.throw("Duplicate value in " + table_fieldname + ": " + link_value)
                    seen_links[link_value] = True
            if table_fieldname == "goal_audience_distribution":
                goal_reference = str(clean.get("goal_reference") or "").strip()
                goal_value = str(clean.get("goal") or "").strip()
                audience_value = str(clean.get("target_audience") or "").strip()
