                if previous_goal and previous_goal != goal_value:
                    frappe.throw("The same Goal Reference cannot point to different goals: " + goal_reference)
                distribution_goal_by_reference[goal_reference] = goal_value
                relation_key = goal_reference + "||" + audience_value
                if distribution_seen.get(relation_key):
                    frappe.throw("Duplicate goal audience relation: " + relation_key)
                distribution_seen[relation_key] = True
                clean["selected"] = 1
                percentage = clean.get("allocation_percentage")
