    source_status = source_values[1] if source_values else ""

    # Never disclose the private URL/token to owner, approver, implementer,
    # closer, assignee or administrator unless that account is the requester.
    if requester != current_user:
        frappe.response["http_status_code"] = 403
        frappe.response["message"] = {"success": False, "message": "Only the requester may evaluate this service."}
    elif source_status != "Closed":
        frappe.response["message"] = {"success": True, "state": "not_closed"}
    else:
        feedback_type_name = frappe.db.get_value(
            "Feedback Type", {"feedback_type_name": "Digital Change Request"}, "name"
        )
        request_values = None
        if feedback_type_name:
