def has_role(role, user_name):
    if user_name == "Administrator":
        return True
    return bool(frappe.db.exists("Has Role", {
        "parent": user_name, "parenttype": "User", "role": role
    }))


def changed_any(fieldnames, current_doc):
    for fieldname in fieldnames:
        if current_doc.has_value_changed(fieldname):
            return True
    return False


def require_fields(fieldnames, stage_label, current_doc):
    missing = []
    for fieldname in fieldnames:
        value = current_doc.get(fieldname)
        if value is None or value == "" or value == []:
            field = current_doc.meta.get_field(fieldname)
            missing.append(field.label if field else fieldname)
    if missing:
        frappe.throw(stage_label + ": Please complete: " + ", ".join(missing))


