def json_string(value):
    if value is None:
        return None

    # If caller already sent a JSON string, keep it if valid.
    if isinstance(value, str):
        try:
            json.loads(value)
            return value
        except Exception:
            return json.dumps(value, ensure_ascii=False)

    return json.dumps(value, ensure_ascii=False)


def bool_int(value):
    if value is True:
        return 1

    if value is False or value is None:
        return 0

    if isinstance(value, str):
        normalized = value.strip().lower()

        if normalized in ["1", "true", "yes", "y", "on"]:
            return 1

        if normalized in ["0", "false", "no", "n", "off", ""]:
            return 0

    return frappe.utils.cint(value)


def int_value(value):
    if value is None or value == "":
        return 0

    return frappe.utils.cint(value)


def get_request_payload():
    payload = {}

    try:
        request_json = frappe.request.get_json(silent=True)

        if request_json:
            payload = request_json
    except Exception:
        pass

    if not payload:
        payload = frappe.form_dict

    return payload


def physical_table_exists():
    """
    We intentionally don't use raw SQL here.

    If the DocType metadata exists but its physical table does not,
    get_value() will raise a DB exception.
    """
    if not frappe.db.exists("DocType", DOCTYPE_NAME):
        return False

    try:
        # Returning None simply means the table is empty.
        # No exception means the physical table exists.
        frappe.db.get_value(DOCTYPE_NAME, {}, "name")
        return True
    except Exception:
        return False


def require_system_manager():
    user = frappe.session.user

    if user == "Administrator":
        return

    has_role = frappe.db.exists(
        "Has Role",
        {
            "parent": user,
            "role": "System Manager"
        }
    )

    if not has_role:
        frappe.throw("System Manager role is required.")


