                "read": 1,
                "write": 1,
                "create": 1,
                "delete": 1,

                "report": 1,
                "export": 1,
                "share": 1,
                "print": 1,
                "email": 1
            }
        ]
    })

    # Creating a DocType through Frappe's Document API invokes the
    # normal DocType schema synchronization and creates tabX Reactions.
    doctype.insert(ignore_permissions=True)

    frappe.db.commit()

    # clear_cache is not documented as a Server Script API method in
    # current v15 documentation. Try it where available, without making
    # the endpoint fail on restricted installations.
    try:
        frappe.clear_cache()
    except Exception:
        pass

    return {
        "created": True,
        "doctype": DOCTYPE_NAME,
        "doctype_exists": bool(
            frappe.db.exists("DocType", DOCTYPE_NAME)
        ),
        "table_exists": physical_table_exists()
    }


# ---------------------------------------------------------
# SAVE / UPSERT
# ---------------------------------------------------------

def save_x_reactions(payload):
    if not frappe.db.exists("DocType", DOCTYPE_NAME):
        frappe.throw(
            "DocType X Reactions does not exist. "
            "Run action=create_doctype first."
        )

    if not physical_table_exists():
        frappe.throw(
            "DocType X Reactions exists, but its physical table is missing."
        )

    # -----------------------------------------------------
    # Locate incoming tweets
    # -----------------------------------------------------

    items = None

    for key in ["data", "results", "tweets", "items"]:
        value = payload.get(key)

        if value is not None:
            items = value
            break

    # Also allow sending one tweet directly as the request body.
    if items is None:
        if payload.get("url") or payload.get("title"):
            items = [payload]
        else:
            items = []

    if isinstance(items, dict):
        items = [items]

    if not isinstance(items, list):
        frappe.throw(
            "Tweet payload must be an object or a list of objects."
        )

    saved = 0
    updated = 0
    errors = []

    index = 0

    for item in items:
        index = index + 1

        try:
            if not isinstance(item, dict):
                raise Exception("Tweet item must be a JSON object.")

            title = item.get("title")
            url = item.get("url")

            if not title:
                raise Exception("Missing required field: title")

            if not url:
                raise Exception("Missing required field: url")

            url = str(url).strip()

            if not url:
                raise Exception("URL cannot be empty.")

            values = {
                "title": title,
                "url": url,

                "date": item.get("date"),
                "author": item.get("author"),
                "source": item.get("source"),
                "domain": item.get("domain"),
                "snippet": item.get("snippet"),

                "likes": int_value(item.get("likes")),
                "retweets": int_value(item.get("retweets")),
                "replies": int_value(item.get("replies")),
                "quotes": int_value(item.get("quotes")),
                "bookmarks": int_value(item.get("bookmarks")),
                "views": int_value(item.get("views")),
                "author_followers": int_value(
                    item.get("author_followers")
                ),

                "author_verified": bool_int(
                    item.get("author_verified")
                ),
                "is_reply": bool_int(
                    item.get("is_reply")
                ),
                "is_quote": bool_int(
                    item.get("is_quote")
                ),

                "lang": item.get("lang"),

                "hashtags": json_string(
                    item.get("hashtags")
                ),
                "user_mentions": json_string(
                    item.get("user_mentions")
                ),
                "sentiment": json_string(
                    item.get("sentiment")
                )
            }

            existing_name = frappe.db.exists(
                DOCTYPE_NAME,
                {
                    "url": url
                }
            )

            # -------------------------------------------------
            # UPDATE
            # -------------------------------------------------

            if existing_name:
                doc = frappe.get_doc(
                    DOCTYPE_NAME,
                    existing_name
                )

                for fieldname in values:
                    doc.set(
                        fieldname,
                        values.get(fieldname)
                    )

                # Do not bypass X Reactions permissions.
                doc.save()

                updated = updated + 1

            # -------------------------------------------------
            # INSERT
            # -------------------------------------------------

            else:
                values["doctype"] = DOCTYPE_NAME

                doc = frappe.get_doc(values)

                # Do not bypass X Reactions permissions.
                doc.insert()

                saved = saved + 1

        except Exception as e:
            errors.append({
                "index": index,
                "url": item.get("url") if isinstance(item, dict) else None,
                "error": str(e)
            })

    frappe.db.commit()

    return {
        "success": len(errors) == 0,
        "received": len(items),
        "saved": saved,
        "updated": updated,
        "errors": errors
    }


# ---------------------------------------------------------
# CHECK
# ---------------------------------------------------------

def check_x_reactions():
    doctype_exists = bool(
        frappe.db.exists("DocType", DOCTYPE_NAME)
    )

    table_exists = False

    if doctype_exists:
        table_exists = physical_table_exists()

    return {
        "doctype": DOCTYPE_NAME,
        "doctype_exists": doctype_exists,
        "table": "tabX Reactions",
        "table_exists": table_exists,
        "ready": doctype_exists and table_exists
    }


